                this.modalInstance = Modal.getOrCreateInstance(modalEl);
                modalEl.addEventListener('hidden.bs.modal', () => {
                    this.resetForm();
                });
            }

            const viewModalEl = document.getElementById('viewWarehouseModal');
            if (viewModalEl) {
                this.viewModalInstance = Modal.getOrCreateInstance(viewModalEl);
            }

            this._themeHandler = (e) => {
                const theme = e.detail?.theme || 'light';
                [this.stockChart, this.skuChart].forEach(chart => {
                    if (chart && typeof chart.updateOptions === 'function') {
                        chart.updateOptions({ 
                            theme: { mode: theme },
                            stroke: chart === this.skuChart ? { width: 2, colors: [theme === 'dark' ? '#212529' : '#fff'] } : undefined
                        });
                    }
                });
            };
            window.addEventListener('themeChanged', this._themeHandler);

            // Clean up when Alpine element is destroyed
            const onHide = () => {
                if (this._themeHandler) {
                    window.removeEventListener('themeChanged', this._themeHandler);
                    this._themeHandler = null;
                }
            };
            window.addEventListener('pagehide', onHide, { once: true });
        },

        async apiRequest(url, options = {}) {
            const { headers, ...otherOptions } = options;
            const response = await fetch(url, {
                headers: {
                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content,
                    'X-Requested-With': 'XMLHttpRequest',
                    'Accept': 'application/json',
                    'Content-Type': 'application/json',
                    ...(headers || {})
                },
                ...otherOptions,
            });

            const text = await response.text();
            const payload = text ? JSON.parse(text) : {};

            if (!response.ok) {
                const validation = payload?.errors ? Object.values(payload.errors).flat().join(' ') : '';
                const message = validation || payload?.message || payload?.error || 'Request failed.';
                throw new Error(message);
            }
            return payload;
        },

        async loadData() {
            this.isLoading = true;
            try {
                const payload = await this.apiRequest(`${this.apiBase}?per_page=1000`);
                this.items = Array.isArray(payload.data) ? payload.data : [];
                this.filterData();
            } catch (error) {
                console.error('Failed to load data:', error);
                showToast(error.message, 'error');
            } finally {
                this.isLoading = false;
            }
        },

        calculateStats() {
            this.stats.total    = this.items.length;
            this.stats.active   = this.items.filter(i => i.status === 'active').length;
            this.stats.inactive = this.items.filter(i => i.status === 'inactive').length;
        },

        filterData() {
            this.filteredItems = this.items.filter(item => {
                const q = this.searchQuery.toLowerCase();
                const matchesSearch = !q ||
                    (item.name || '').toLowerCase().includes(q) ||
                    (item.code || '').toLowerCase().includes(q) ||
                    (item.city || '').toLowerCase().includes(q) ||
                    (item.state || '').toLowerCase().includes(q) ||
                    (item.gstin || '').toLowerCase().includes(q);

                const matchesStatus = !this.statusFilter || item.status === this.statusFilter;
                return matchesSearch && matchesStatus;
            });

            this.sortData();
            this.calculateStats();
            this.currentPage = 1;
            this.selectedItems = [];

            // Re-render charts after filtering to keep them synchronized
            setTimeout(() => this.renderCharts(), 100);
        },

        renderCharts() {
            if (typeof window.ApexCharts === 'undefined') return;

            const items = this.filteredItems || [];

            const warehouseNames = items.map(i => i.name || `WH-${i.id}`);
            const physicalStock = items.map(i => parseFloat(i.total_physical_stock || 0));
            const totalSkus = items.map(i => parseFloat(i.total_skus || 0));

            const currentTheme = document.documentElement.getAttribute('data-bs-theme') || 'light';

            // Stock Distribution Chart (Bar)
            const stockOptions = {
                series: [{ name: 'Physical Stock', data: physicalStock }],
                chart: { 
                    type: 'bar', 
                    height: 300, 
                    toolbar: { show: false },
                    background: 'transparent'
                },
                theme: { mode: currentTheme },
                plotOptions: { bar: { borderRadius: 6, horizontal: false, columnWidth: '40%' } },
                dataLabels: { enabled: false },
                xaxis: { categories: warehouseNames, tooltip: { enabled: false } },
                colors: ['#0d6efd'],
                grid: { strokeDashArray: 4 },
                tooltip: { y: { formatter: val => val.toLocaleString() + ' Units' } }
            };

            if (this.stockChart) {
                this.stockChart.updateOptions(stockOptions);
            } else {
                const el = document.querySelector("#stockDistributionChart");
                if (el) {
                    this.stockChart = new window.ApexCharts(el, stockOptions);
                    this.stockChart.render();
                }
            }

            // SKU Spread Chart (Donut)
            const hasSkuData = totalSkus.some(v => v > 0);
            const skuOptions = {
                series: hasSkuData ? totalSkus : [1],
                chart: { 
                    type: 'donut', 
                    height: 300,
                    background: 'transparent'
                },
                theme: { mode: currentTheme },
                labels: hasSkuData ? warehouseNames : ['No Data'],
                colors: hasSkuData ? ['#198754', '#0dcaf0', '#ffc107', '#fd7e14', '#dc3545', '#6f42c1', '#20c997'] : ['#e9ecef'],
                dataLabels: { enabled: hasSkuData, dropShadow: { enabled: false } },
                stroke: { width: 2, colors: [currentTheme === 'dark' ? '#212529' : '#fff'] },
                legend: { position: 'bottom', markers: { radius: 12 } },
                tooltip: { y: { formatter: val => hasSkuData ? val.toLocaleString() + ' SKUs' : '0 SKUs' } }
            };

            if (this.skuChart) {
                this.skuChart.updateOptions(skuOptions);
            } else {
                const el = document.querySelector("#skuSpreadChart");
                if (el) {
                    this.skuChart = new window.ApexCharts(el, skuOptions);
                    this.skuChart.render();
                }
            }
        },

        sortData() {
            this.filteredItems.sort((a, b) => {
                let aVal = a[this.sortField] || '';
                let bVal = b[this.sortField] || '';

                if (this.sortField === 'id') {
                    aVal = parseInt(aVal) || 0;
                    bVal = parseInt(bVal) || 0;
                } else {
                    aVal = String(aVal).toLowerCase();
                    bVal = String(bVal).toLowerCase();
                }

                if (this.sortDirection === 'asc') return aVal > bVal ? 1 : -1;
                return aVal < bVal ? 1 : -1;
            });
        },

        sortBy(field) {
            if (this.sortField === field) {
                this.sortDirection = this.sortDirection === 'asc' ? 'desc' : 'asc';
            } else {
                this.sortField = field;
                this.sortDirection = 'asc';
            }
            this.sortData();
        },

        get paginatedItems() {
            const start = (this.currentPage - 1) * this.itemsPerPage;
            return this.filteredItems.slice(start, start + this.itemsPerPage);
        },

        get pageFrom() {
            if (this.filteredItems.length === 0) return 0;
            return (this.currentPage - 1) * this.itemsPerPage + 1;
        },

        get pageTo() {
            return Math.min(this.currentPage * this.itemsPerPage, this.filteredItems.length);
        },

        get totalPages() {
            return Math.ceil(this.filteredItems.length / this.itemsPerPage);
        },

        get visiblePages() {
            if (this.totalPages <= 1) return [1];
            const pages = [1];

            if (this.totalPages <= 7) {
                for (let i = 2; i <= this.totalPages; i++) pages.push(i);
            } else {
                if (this.currentPage <= 4) {
                    for (let i = 2; i <= 5; i++) pages.push(i);
                    pages.push('...');
                    pages.push(this.totalPages);
                } else if (this.currentPage >= this.totalPages - 3) {
                    pages.push('...');
                    for (let i = this.totalPages - 4; i <= this.totalPages; i++) pages.push(i);
                } else {
                    pages.push('...');
                    for (let i = this.currentPage - 1; i <= this.currentPage + 1; i++) pages.push(i);
                    pages.push('...');
                    pages.push(this.totalPages);
                }
            }
            return pages;
        },

        goToPage(page) {
            if (page >= 1 && page <= this.totalPages) {
                this.currentPage = page;
            }
        },

        toggleAll(checked) {
      if (checked) {
        this.paginatedItems.forEach(item => {
          if (!this.selectedItems.includes(String(item.id))) {
            this.selectedItems.push(String(item.id));
          }
        });
      } else {
        const currentIds = this.paginatedItems.map(item => String(item.id));
        this.selectedItems = this.selectedItems.filter(id => !currentIds.includes(id));
      }
    },

        toggleItem(id) {
            if (this.selectedItems.includes(id)) {
                this.selectedItems = this.selectedItems.filter(i => i !== id);
            } else {
                this.selectedItems.push(id);
            }
        },

        resetForm() {
            this.isEditing = false;
            this.form = emptyForm();
            this.villageSearchQuery = '';
            this.villageResults = [];
        },

        openCreateModal() {
            this.resetForm();
            this.modalInstance?.show();
        },

        viewItem(item) {
            this.viewData = { ...item };
            this.viewModalInstance?.show();
        },

        editItem(item) {
            this.isEditing = true;
            this.form = {
                id:             item.id,
                name:           item.name || '',
                code:           item.code || '',
                company_name:   item.company_name || '',
                gstin:          item.gstin || '',
                phone:          item.phone || '',
                email:          item.email || '',
                reference_no:   item.reference_no || '',
                seed_lic_no:    item.seed_lic_no || '',
                pesti_lic_no:   item.pesti_lic_no || '',
                address_line_1: item.address_line_1 || '',
                address_line_2: item.address_line_2 || '',
                village_id:     item.village_id || '',
                village_name:   item.village_name || '',
                post_office:    item.post_office || '',
                taluka:         item.taluka || '',
                city:           item.city || '',
                state:          item.state || '',
                pincode:        item.pincode || '',
                is_default:     !!item.is_default,
                status:         item.status || 'active',
            };
            this.villageSearchQuery = item.village_name || '';
            this.villageResults = [];
            this.modalInstance?.show();
        },

        async saveItem() {
            if (!this.form.name.trim()) {
                showToast('Warehouse name is required.', 'warning');
                return;
            }

            this.saving = true;
            try {
                const url    = this.isEditing ? `${this.apiBase}/${this.form.id}` : this.apiBase;
                const method = this.isEditing ? 'PUT' : 'POST';

                const payload = { ...this.form };

                await this.apiRequest(url, {
                    method,
                    body: JSON.stringify(payload),
                });

                showToast(`Warehouse ${this.isEditing ? 'updated' : 'created'} successfully.`, 'success');
                this.modalInstance?.hide();
                await this.loadData();
            } catch (error) {
                showToast(error.message, 'error');
            } finally {
                this.saving = false;
            }
        },

        async deleteItem(item) {
            const name = item.name || item.code;
            const confirmed = await confirmDelete({
                title: 'Delete Warehouse?',
                text: `Are you sure you want to delete "${name}"? This action cannot be undone.`,
            });
            if (!confirmed) return;

            try {
                await this.apiRequest(`${this.apiBase}/${item.id}`, { method: 'DELETE' });
                showToast('Warehouse deleted successfully.', 'success');
                await this.loadData();
            } catch (error) {
                showToast(error.message, 'error');
            }
        },

        async bulkAction(action) {
            if (this.selectedItems.length === 0) {
                showToast('Please select at least one warehouse.', 'warning');
                return;
            }

            try {
                if (action === 'delete') {
                    const confirmed = await confirmDelete({
                        title: 'Delete Selected?',
                        text: `Are you sure you want to delete ${this.selectedItems.length} warehouses?`,
                    });
                    if (!confirmed) return;

                    for (const id of this.selectedItems) {
                        await this.apiRequest(`${this.apiBase}/${id}`, { method: 'DELETE' });
                    }
                } else {
                    const status = action;
                    for (const id of this.selectedItems) {
                        await this.apiRequest(`${this.apiBase}/${id}`, {
                            method: 'PUT',
                            body: JSON.stringify({ status }),
                        });
                    }
                }

                this.selectedItems = [];
                showToast('Bulk action completed successfully.', 'success');
                await this.loadData();
            } catch (error) {
                showToast(error.message || 'Bulk action failed.', 'error');
            }
        },

        // ─── Village Autofill ──────────────────────────────────────────────────────

        onVillageInput() {
            clearTimeout(this.villageSearchTimeout);
            if (this.villageSearchQuery.length < 3) {
                this.villageResults = [];
                return;
            }
            this.villageSearchTimeout = setTimeout(() => this.searchVillages(), 300);
        },

        async searchVillages() {
            if (this.villageSearchQuery.trim().length < 3) {
                this.villageResults = [];
                return;
            }
            this.villageSearchLoading = true;
            try {
                const res = await this.apiRequest(`/api/villages/search?q=${encodeURIComponent(this.villageSearchQuery)}`);
                this.villageResults = res.data ?? [];
            } catch (e) {
                console.error('Village search failed:', e);
            } finally {
                this.villageSearchLoading = false;
            }
        },

        selectVillage(v) {
            this.form.village_id   = v.id;
            this.form.village_name = v.village_name;
            this.form.city         = v.taluka_name || v.district_name || '';
            this.form.state        = v.state_name || '';
            this.form.pincode      = v.pincode || '';
            this.form.post_office  = v.post_so_name || '';
            this.form.taluka       = v.taluka_name || '';
            this.villageSearchQuery = v.village_name;
            this.villageResults = [];
        },

        clearVillage() {
            this.form.village_id   = '';
            this.form.village_name = '';
            this.form.city         = '';
            this.form.state        = '';
            this.form.pincode      = '';
            this.form.post_office  = '';
            this.form.taluka       = '';
            this.villageSearchQuery = '';
            this.villageResults = [];
        },

        exportData() {
            if (this.filteredItems.length === 0) {
                showToast('No data to export.', 'warning');
                return;
            }

            const headers = ['ID', 'Name', 'Code', 'Company', 'GSTIN', 'Phone', 'Email', 'Reference No', 'Seed Lic No', 'Pesti Lic No', 'Address', 'City', 'State', 'Pincode', 'Status', 'Default'];
            const csvRows = [headers.join(',')];

            this.filteredItems.forEach(item => {
                const addr = [item.address_line_1, item.address_line_2].filter(Boolean).join(', ');
                const values = [
                    item.id,
                    `"${(item.name || '').replace(/"/g, '""')}"`,
                    item.code || '',
                    `"${(item.company_name || '').replace(/"/g, '""')}"`,
                    item.gstin || '',
                    item.phone || '',
                    item.email || '',
                    `"${(item.reference_no || '').replace(/"/g, '""')}"`,
                    `"${(item.seed_lic_no || '').replace(/"/g, '""')}"`,
                    `"${(item.pesti_lic_no || '').replace(/"/g, '""')}"`,
                    `"${addr.replace(/"/g, '""')}"`,
                    item.city || '',
                    item.state || '',
                    item.pincode || '',
                    item.status,
                    item.is_default ? 'Yes' : 'No',
                ];
                csvRows.push(values.join(','));
            });

            const blob = new Blob([csvRows.join('\n')], { type: 'text/csv' });
            const url  = URL.createObjectURL(blob);
            const a    = document.createElement('a');
            a.setAttribute('href', url);
            a.setAttribute('download', 'warehouses_export.csv');
            a.click();
            URL.revokeObjectURL(url);
        },
    };

    window.Alpine.store('warehousesTable', instance);
    return instance;
};

import Alpine from 'alpinejs';
import ApexCharts from 'apexcharts';
import { Modal } from 'bootstrap';
import Swal from 'sweetalert2';

// ─── CSRF helper ─────────────────────────────────────────────────────────────
function getCsrfToken() {
  return document.querySelector('meta[name="csrf-token"]')?.content ?? '';
}

async function apiFetch(url, options = {}) {
  const { headers, ...otherOptions } = options;
  const res = await fetch(url, {
    headers: {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      'X-CSRF-TOKEN': getCsrfToken(),
      ...(headers || {}),
    },
    ...otherOptions,
  });

  const text = await res.text();
  const data = text ? JSON.parse(text) : {};

  if (!res.ok) {
    const validation = data?.errors ? Object.values(data.errors).flat().join(' ') : '';
    const message = validation || data?.message || data?.error || 'Request failed';
    throw new Error(message);
  }

  return data;
}

function getModal(elementOrSelector) {
  const element = typeof elementOrSelector === 'string'
    ? document.querySelector(elementOrSelector)
    : elementOrSelector;

  return element ? Modal.getOrCreateInstance(element) : null;
}

// ─── Toast helper ─────────────────────────────────────────────────────────────
function showToast(message, type = 'success') {
  const container = document.getElementById('toast-container');
  if (!container) return;

  const id = 'toast-' + Date.now();
  const iconMap = {
    success: 'bi-check-circle-fill',
    danger:  'bi-x-circle-fill',
    warning: 'bi-exclamation-triangle-fill',
    info:    'bi-info-circle-fill',
  };

  const el = document.createElement('div');
  el.id = id;
  el.className = `toast align-items-center text-bg-${type} border-0 show mb-2`;
  el.setAttribute('role', 'alert');
  el.innerHTML = `
    <div class="d-flex">
      <div class="toast-body">
        <i class="bi ${iconMap[type] ?? 'bi-info-circle-fill'} me-2"></i><span></span>
      </div>
      <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast"></button>
    </div>`;
  el.querySelector('.toast-body span').textContent = message;

  container.appendChild(el);
  setTimeout(() => el.remove(), 4000);
}

async function confirmDelete({ title, text, confirmButtonText = 'Yes, delete it' }) {
  const result = await Swal.fire({
    title,
    text,
    icon: 'warning',
    showCancelButton: true,
    confirmButtonText,
    cancelButtonText: 'Cancel',
    confirmButtonColor: '#dc3545',
    reverseButtons: true,
    focusCancel: true,
  });

  return result.isConfirmed;
}

function downloadBlob(filename, content, contentType) {
  const blob = new Blob([content], { type: contentType });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  URL.revokeObjectURL(link.href);
  document.body.removeChild(link);
}

function csvEscape(value) {
  return `"${String(value ?? '').replace(/"/g, '""')}"`;
}

function parseCsvLine(line) {
  const values = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const next = line[i + 1];

    if (char === '"' && inQuotes && next === '"') {
      current += '"';
      i++;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      values.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }

  values.push(current.trim());
  return values;
}

document.addEventListener('alpine:init', () => {


  // ─── Customer Table Controller ─────────────────────────────────────────────
  Alpine.data('customerTable', () => ({
    customers: [],
    isLoading: false,
    currentPage: 1,
    totalPages: 1,
    totalCustomers: 0,
    itemsPerPage: 15,

    // Filters
    searchQuery: '',
    statusFilter: '',
    categoryFilter: '',
    sortField: 'name',
    sortDirection: 'asc',

    // Selection
    selectedCustomers: [],

    get selectedRows() {
      return this.customers.filter(c => this.selectedCustomers.includes(c.id));
    },

    get hasSelectedDeletedCustomers() {
      return this.selectedRows.some(c => c.isDeleted);
    },

    get hasSelectedActiveCustomers() {
      return this.selectedRows.some(c => !c.isDeleted);
    },

    // Charts & Trends
    growthPeriod: 7,
    charts: {},

    init() {
      this.loadCustomers();
      // Listen for customer changes to refresh stats/charts
      window.addEventListener('customer-updated', () => this.loadCustomers());
    },

    async loadCustomers() {
      this.isLoading = true;
      try {
        const params = new URLSearchParams({
          page: this.currentPage,
          per_page: this.itemsPerPage,
          sort_by: this.sortField,
          sort_dir: this.sortDirection,
        });

        if (this.searchQuery) params.set('search', this.searchQuery);
        if (this.statusFilter) {
          if (this.statusFilter === 'deleted') {
            params.set('deleted', 'only');
          } else {
            params.set('status', this.statusFilter);
          }
        }
        if (this.categoryFilter) params.set('category', this.categoryFilter);

        const data = await apiFetch(`/api/customers?${params.toString()}`);

        this.customers = (data.data ?? []).map(c => this._mapCustomer(c));
        this.currentPage = data.current_page ?? 1;
        this.totalPages = data.last_page ?? 1;
        this.totalCustomers = data.total ?? 0;

        this.$nextTick(() => {
          this.initCharts();
        });
      } catch (err) {
        showToast('Failed to load customers: ' + err.message, 'danger');
      } finally {
        this.isLoading = false;
      }
    },

    _mapCustomer(c) {
      const first = c.firstname ?? '';
      const last = c.lastname ?? '';
      const initials = ((first[0] ?? '') + (last[0] ?? '')).toUpperCase();
      const cropsList = Array.isArray(c.crops) ? c.crops : (typeof c.crops === 'string' ? JSON.parse(c.crops || '[]') : []);
      const irrigationList = Array.isArray(c.irrigation_type) ? c.irrigation_type : (typeof c.irrigation_type === 'string' ? JSON.parse(c.irrigation_type || '[]') : []);

      return {
        ...c,
        name: [c.firstname, c.middlename, c.lastname].filter(Boolean).join(' '),
        initials: initials || 'C',
        isDeleted: !!c.deleted_at,
        cropsList,
        irrigationList,
        formattedOutstanding: 'Rs ' + Number(c.outstanding_balance || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
        joinDate: c.created_at ? new Date(c.created_at).toLocaleDateString() : '—',
      };
    },

    // Pagination
    goToPage(page) {
      if (page < 1 || page > this.totalPages) return;
      this.currentPage = page;
      this.loadCustomers();
    },

    get visiblePages() {
      const pages = [];
      const delta = 2;
      for (let i = Math.max(1, this.currentPage - delta); i <= Math.min(this.totalPages, this.currentPage + delta); i++) {
        pages.push(i);
      }
      return pages;
    },

    get pageFrom() {
      if (this.totalCustomers === 0) return 0;
      return (this.currentPage - 1) * this.itemsPerPage + 1;
    },

    get pageTo() {
      return Math.min(this.currentPage * this.itemsPerPage, this.totalCustomers);
    },

    // Sorting
    sort(field) {
      if (this.sortField === field) {
        this.sortDirection = this.sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        this.sortField = field;
        this.sortDirection = 'asc';
      }
      this.currentPage = 1;
      this.loadCustomers();
    },

    searchCustomers() {
      this.currentPage = 1;
      this.loadCustomers();
    },

    filterCustomers() {
      this.currentPage = 1;
      this.loadCustomers();
    },

    getSortIcon(field) {
      if (this.sortField !== field) return 'bi-arrow-down-up text-muted small';
      return this.sortDirection === 'asc' ? 'bi-arrow-up text-primary' : 'bi-arrow-down text-primary';
    },

    resetFilters() {
      this.searchQuery = '';
      this.statusFilter = '';
      this.categoryFilter = '';
      this.currentPage = 1;
      this.loadCustomers();
    },

    // Selection
    toggleAll(checked) {
      if (checked) {
        this.customers.forEach(item => {
          if (!this.selectedCustomers.includes(String(item.id))) {
            this.selectedCustomers.push(String(item.id));
          }
        });
      } else {
        const currentIds = this.customers.map(item => String(item.id));
        this.selectedCustomers = this.selectedCustomers.filter(id => !currentIds.includes(id));
      }
    },

    toggleCustomer(id) {
      if (this.selectedCustomers.includes(id)) {
        this.selectedCustomers = this.selectedCustomers.filter(i => i !== id);
      } else {
        this.selectedCustomers = [...this.selectedCustomers, id];
      }
    },

    // Actions
    editCustomer(c) {
      window.dispatchEvent(new CustomEvent('open-add-customer-modal', { detail: { customer: c } }));
    },

    openCreateCustomer() {
      window.dispatchEvent(new CustomEvent('open-add-customer-modal'));
    },

    viewCustomer(c) {
      const profile = Alpine.$data(document.querySelector('[x-data="customerProfile"]'));
      if (profile) profile.loadProfile(c.id);
      getModal('#viewCustomerModal')?.show();
    },

    async deleteCustomer(c) {
      const confirmed = await confirmDelete({
        title: 'Temporarily delete customer?',
        text: `Move ${c.name} to deleted. Outstanding balances will be preserved.`,
        confirmButtonText: 'Yes, delete',
      });
      if (!confirmed) return;

      try {
        const res = await apiFetch(`/api/customers/${c.id}`, { method: 'DELETE' });
        showToast(res.message, 'success');
        this.loadCustomers();
      } catch (err) {
        showToast(err.message, 'danger');
      }
    },

    async restoreCustomer(c) {
      try {
        const res = await apiFetch(`/api/customers/${c.id}/restore`, { method: 'PATCH' });
        showToast(res.message, 'success');
        this.loadCustomers();
      } catch (err) {
        showToast(err.message, 'danger');
      }
    },

    async forceDeleteCustomer(c) {
      const confirmed = await confirmDelete({
        title: 'Permanently delete customer?',
        text: `This will permanently delete ${c.name} and all associated addresses. This cannot be undone.`,
        confirmButtonText: 'Permanently Delete',
      });
      if (!confirmed) return;

      try {
        const res = await apiFetch(`/api/customers/${c.id}/force`, { method: 'DELETE' });
        showToast(res.message, 'success');
        this.loadCustomers();
      } catch (err) {
        showToast(err.message, 'danger');
      }
    },

    async bulkAction(action) {
      if (this.selectedCustomers.length === 0) {
        showToast('Please select customers first.', 'warning');
        return;
      }

      if (action === 'delete') {
        const confirmed = await confirmDelete({
          title: 'Temporarily delete selected customers?',
          text: `Do you want to move ${this.selectedCustomers.length} selected customer(s) to deleted customers? You can restore them later.`,
          confirmButtonText: 'Yes, delete customers',
        });
        if (!confirmed) return;
      }
      if (action === 'force-delete') {
        const confirmed = await confirmDelete({
          title: 'Permanently delete selected customers?',
          text: `This will permanently delete ${this.selectedCustomers.length} selected customer(s). This action cannot be undone.`,
          confirmButtonText: 'Yes, permanently delete',
        });
        if (!confirmed) return;
      }
      if (action === 'restore') {
        const confirmed = await confirmDelete({
          title: 'Restore selected customers?',
          text: `Are you sure you want to restore ${this.selectedCustomers.length} selected customer(s)?`,
          confirmButtonText: 'Yes, restore customers',
        });
        if (!confirmed) return;
      }

      try {
        const res = await apiFetch('/api/customers/bulk-action', {
          method: 'POST',
          body: JSON.stringify({ action, ids: this.selectedCustomers }),
        });
        showToast(res.message, 'success');
        this.selectedCustomers = [];
        this.loadCustomers();
      } catch (err) {
        showToast(err.message, 'danger');
      }
    },

    // Stats calculations
    get stats() {
      const active = this.customers.filter(c => c.status === 'active').length;
      const blacklisted = this.customers.filter(c => c.is_blacklisted).length;
      const kycCompleted = this.customers.filter(c => c.kyc_completed).length;

      return {
        total: this.totalCustomers,
        active,
        blacklisted,
        kycPercentage: this.customers.length > 0 ? (kycCompleted / this.customers.length) * 100 : 0,
      };
    },

    get cropStats() {
      const counts = {};
      this.customers.forEach(c => {
        c.cropsList.forEach(crop => {
          counts[crop] = (counts[crop] || 0) + 1;
        });
      });
      const colors = ['#6366f1','#10b981','#f59e0b','#ef4444','#8b5cf6','#06b6d4'];
      return Object.entries(counts).map(([name, count], i) => ({
        name, count,
        percentage: this.customers.length > 0 ? Math.round((count / this.customers.length) * 100) : 0,
        color: colors[i % colors.length],
      })).sort((a,b) => b.count - a.count).slice(0, 5);
    },

    // Charts
    initCharts() {
      this._initSparkline();
      this._initGrowthChart();
      this._initCategoryChart();
    },

    setGrowthPeriod(days) {
      this.growthPeriod = Number(days);
      this.$nextTick(() => {
        if (this.charts.customerGrowth) {
          this.charts.customerGrowth.destroy();
          delete this.charts.customerGrowth;
        }
        document.querySelector('#customerGrowthChart')?.removeAttribute('data-chart-initialized');
        this._initGrowthChart();
      });
    },

    _initSparkline() {
      const el = document.querySelector('#activeCustomerChart');
      if (!el || el.hasAttribute('data-chart-initialized')) return;
      el.setAttribute('data-chart-initialized', 'true');
      this.charts.activeCustomers = new ApexCharts(el, {
        series: [{ name: 'KYC Verified', data: [40, 45, 52, 58, 65, 72, 78] }],
        chart: { type: 'line', height: 50, sparkline: { enabled: true } },
        stroke: { curve: 'smooth', width: 2 },
        colors: ['#10b981'],
      });
      this.charts.activeCustomers.render();
    },

    _initGrowthChart() {
      const el = document.querySelector('#customerGrowthChart');
      if (!el || el.hasAttribute('data-chart-initialized')) return;
      el.setAttribute('data-chart-initialized', 'true');

      const period = Number(this.growthPeriod) || 7;
      const dayCounts = new Array(period).fill(0);
      const dayLabels = [];
      const now = new Date();
      for (let i = period - 1; i >= 0; i--) {
        const d = new Date(now);
        d.setDate(d.getDate() - i);
        dayLabels.push(d.toLocaleDateString('en', period <= 7 ? { weekday: 'short' } : { month: 'short', day: 'numeric' }));
        dayCounts[period - 1 - i] = this.customers.filter(c => {
          const j = new Date(c.created_at);
          return j.toDateString() === d.toDateString();
        }).length;
      }

      this.charts.customerGrowth = new ApexCharts(el, {
        series: [{ name: 'New Registrations', data: dayCounts }],
        chart: { type: 'bar', height: 250, width: '100%', toolbar: { show: false } },
        colors: ['#6366f1'],
        plotOptions: { bar: { borderRadius: 4, columnWidth: '50%' } },
        xaxis: {
          categories: dayLabels,
          labels: { style: { colors: '#64748b', fontSize: '12px' } }
        },
        yaxis: { show: false },
        grid: { show: false },
        dataLabels: { enabled: false },
      });
      this.charts.customerGrowth.render();
    },

    _initCategoryChart() {
      const el = document.querySelector('#categoryDistributionChart');
      if (!el || el.hasAttribute('data-chart-initialized')) return;
      el.setAttribute('data-chart-initialized', 'true');

      const catCounts = this.customers.reduce((acc, c) => {
        const cat = c.category || 'individual';
        acc[cat] = (acc[cat] || 0) + 1;
        return acc;
      }, { individual: 0, business: 0 });

      this.charts.categoryChart = new ApexCharts(el, {
        series: [catCounts.individual, catCounts.business],
        chart: { type: 'donut', height: 160 },
        labels: ['Individual/Farmer', 'Business/Dealer'],
        colors: ['#6366f1', '#06b6d4'],
        legend: { position: 'bottom', labels: { colors: '#64748b' } },
        dataLabels: { enabled: false }
      });
      this.charts.categoryChart.render();
    },

    async fetchAllFilteredCustomers() {
      const first = await apiFetch(`/api/customers?page=1&per_page=100&sort_by=${this.sortField}&sort_dir=${this.sortDirection}`);
      const mapped = (first.data ?? []).map(c => this._mapCustomer(c));
      const lastPage = first.last_page ?? 1;

      for (let page = 2; page <= lastPage; page++) {
        const data = await apiFetch(`/api/customers?page=${page}&per_page=100&sort_by=${this.sortField}&sort_dir=${this.sortDirection}`);
        mapped.push(...(data.data ?? []).map(c => this._mapCustomer(c)));
      }
      return mapped;
    },

    async exportCustomers() {
      try {
        const list = await this.fetchAllFilteredCustomers();
        const headers = ['ID','Code','Name','Email','Phone','Category','Outstanding Balance','Credit Limit','Credit Days','Crops','Irrigation Source','KYC Status','Account Status','Joined'];
        const rows = list.map(c => [
          c.id, c.party_code, c.name, c.email || '', c.phone || '', c.category || 'individual',
          c.outstanding_balance, c.credit_limit, c.credit_days,
          c.cropsList.join('; '), c.irrigationList.join('; '),
          c.kyc_completed ? 'Verified' : 'Pending', c.status, c.joinDate
        ]);
        const csv = [headers, ...rows].map(r => r.map(csvEscape).join(',')).join('\n');
        downloadBlob('customers-export.csv', csv, 'text/csv;charset=utf-8;');
        showToast(`Exported ${list.length} customer(s).`);
      } catch (err) {
        showToast('Export failed: ' + err.message, 'danger');
      }
    }
  }));


  // ─── Customer Profile & Address Manager Controller ──────────────────────────
  Alpine.data('customerProfile', () => ({
    customer: null,
    loading: false,
    savingAddress: false,

    // Address Form
    showAddressForm: false,
    editingAddressId: null,
    addressForm: {
      label: 'Primary',
      address_line_1: '',
      address_line_2: '',
      village_id: '',
      village_name: '',
      city: '',
      state: '',
      pincode: '',
      is_default: false,
    },

    // Village Autocomplete Search
    villageSearchQuery: '',
    villageResults: [],

    async loadProfile(id) {
      this.loading = true;
      this.showAddressForm = false;
      try {
        const data = await apiFetch(`/api/customers/${id}`);
        this.customer = this._mapProfileCustomer(data.data ?? data);
      } catch (err) {
        showToast('Failed to load profile: ' + err.message, 'danger');
      } finally {
        this.loading = false;
      }
    },

    _mapProfileCustomer(c) {
      const first = c.firstname ?? '';
      const last = c.lastname ?? '';
      const initials = ((first[0] ?? '') + (last[0] ?? '')).toUpperCase();
      const cropsList = Array.isArray(c.crops) ? c.crops : (typeof c.crops === 'string' ? JSON.parse(c.crops || '[]') : []);
      const irrigationList = Array.isArray(c.irrigation_type) ? c.irrigation_type : (typeof c.irrigation_type === 'string' ? JSON.parse(c.irrigation_type || '[]') : []);

      return {
        ...c,
        name: [c.firstname, c.middlename, c.lastname].filter(Boolean).join(' '),
        initials: initials || 'C',
        isDeleted: !!c.deleted_at,
        cropsList,
        irrigationList,
        formattedOutstanding: 'Rs ' + Number(c.outstanding_balance || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
      };
    },

    editFromProfile() {
      getModal('#viewCustomerModal')?.hide();
      const table = Alpine.$data(document.querySelector('[x-data="customerTable"]'));
      if (table) table.editCustomer(this.customer);
    },

    async toggleActiveStatus() {
      try {
        const res = await apiFetch(`/api/customers/${this.customer.id}/toggle-active`, { method: 'PATCH' });
        showToast(res.message);
        this.customer.is_active = res.is_active;
        this.customer.status = res.is_active ? 'active' : 'inactive';
        window.dispatchEvent(new CustomEvent('customer-updated'));
      } catch (err) {
        showToast(err.message, 'danger');
      }
    },

    // Addresses CRUD
    startAddAddress() {
      // Hide View Profile Modal
      getModal('#viewCustomerModal')?.hide();

      this.editingAddressId = null;
      this.villageSearchQuery = '';
      this.villageResults = [];
      this.addressForm = {
        label: 'Home',
        address_line_1: '',
        address_line_2: '',
        village_id: '',
        village_name: '',
        city: '',
        state: '',
        pincode: '',
        post_so_name: '',
        taluka_name: '',
        district_name: '',
        state_name: '',
        is_default: this.customer?.addresses?.length === 0,
      };

      // Show Address Modal
      getModal('#addressModal')?.show();
    },

    startEditAddress(addr) {
      // Hide View Profile Modal
      getModal('#viewCustomerModal')?.hide();

      this.editingAddressId = addr.id;
      this.villageSearchQuery = addr.village?.village_name ?? '';
      this.villageResults = [];
      this.addressForm = {
        label: addr.label ?? 'Primary',
        address_line_1: addr.address_line_1 ?? '',
        address_line_2: addr.address_line_2 ?? '',
        village_id: addr.village_id ?? '',
        village_name: addr.village?.village_name ?? '',
        city: addr.city ?? '',
        state: addr.state ?? '',
        pincode: addr.pincode ?? '',
        post_so_name: addr.village?.post_so_name ?? '',
        taluka_name: addr.village?.taluka_name ?? '',
        district_name: addr.village?.district_name ?? '',
        state_name: addr.village?.state_name ?? addr.state ?? '',
        is_default: !!addr.is_default,
      };

      // Show Address Modal
      getModal('#addressModal')?.show();
    },

    cancelAddressForm() {
      getModal('#addressModal')?.hide();
      getModal('#viewCustomerModal')?.show();
    },

    async searchVillages() {
      if (this.villageSearchQuery.trim().length === 0) {
        this.addressForm.village_id = '';
        this.addressForm.village_name = '';
        this.addressForm.city = '';
        this.addressForm.state = '';
        this.addressForm.pincode = '';
        this.addressForm.post_so_name = '';
        this.addressForm.taluka_name = '';
        this.addressForm.district_name = '';
        this.addressForm.state_name = '';
      }
      if (this.villageSearchQuery.length < 3) {
        this.villageResults = [];
        return;
      }
      try {
        const data = await apiFetch(`/api/villages/search?q=${encodeURIComponent(this.villageSearchQuery)}`);
        this.villageResults = data.data ?? [];
      } catch (err) {
        console.error(err);
      }
    },

    selectVillage(v) {
      this.addressForm.village_id = v.id;
      this.addressForm.village_name = v.village_name;
      this.addressForm.city = v.taluka_name || v.district_name || '';
      this.addressForm.state = v.state_name || '';
      this.addressForm.pincode = v.pincode || '';
      this.addressForm.post_so_name = v.post_so_name || '';
      this.addressForm.taluka_name = v.taluka_name || '';
      this.addressForm.district_name = v.district_name || '';
      this.addressForm.state_name = v.state_name || '';
      this.villageSearchQuery = v.village_name;
      this.villageResults = [];
    },

    async saveAddress() {
      this.savingAddress = true;
      try {
        const f = this.addressForm;

        // Always include status; derive city/state/pincode from village when available
        const payload = {
          label:          f.label,
          status:         'active',
          address_line_1: f.address_line_1,
          address_line_2: f.address_line_2 || '',
          village_id:     f.village_id || null,
          city:           f.city || f.taluka_name || f.district_name || '',
          state:          f.state || f.state_name || '',
          pincode:        f.pincode || '',
          is_default:     f.is_default,
        };

        const url = this.editingAddressId 
          ? `/api/customers/${this.customer.id}/addresses/${this.editingAddressId}`
          : `/api/customers/${this.customer.id}/addresses`;
        const method = this.editingAddressId ? 'PATCH' : 'POST';

        const res = await apiFetch(url, {
          method,
          body: JSON.stringify(payload)
        });

        showToast(res.message || 'Address saved successfully.', 'success');

        // Hide Address Modal
        getModal('#addressModal')?.hide();

        // Reload customer profile to refresh addresses list
        await this.loadProfile(this.customer.id);

        // Reopen View Profile Modal
        getModal('#viewCustomerModal')?.show();
      } catch (err) {
        showToast(err.message, 'danger');
      } finally {
        this.savingAddress = false;
      }
    },

    async deleteAddress(addr) {
      const confirmed = await confirmDelete({
        title: 'Delete Address?',
        text: `Are you sure you want to delete the address labeled "${addr.label}"?`,
      });
      if (!confirmed) return;

      try {
        const res = await apiFetch(`/api/customers/${this.customer.id}/addresses/${addr.id}`, {
          method: 'DELETE'
        });
        showToast(res.message, 'success');
        this.loadProfile(this.customer.id);
      } catch (err) {
        showToast(err.message, 'danger');
      }
    }
  }));

  // ─── importForm ─────────────────────────────────────────────────────────────
  Alpine.data('importForm', () => ({
    file:     null,
    importing: false,
    result:   null,

    async importCustomers() {
      if (!this.file) {
        showToast('Please select a CSV file.', 'warning');
        return;
      }
      this.importing = true;
      this.result    = null;

      const text = await this.file.text();
      const lines = text.trim().split('\n').filter(l => l.trim());
      if (lines.length < 2) {
        showToast('CSV file is empty or has no data rows.', 'warning');
        this.importing = false;
        return;
      }

      // Format: firstname, middlename, lastname, email, phone, category, status, company_name, kyc_completed
      let created = 0;
      let errors  = [];

      for (let i = 1; i < lines.length; i++) {
        const values = parseCsvLine(lines[i]);
        const [firstname, middlename, lastname, email, phone, category, statusRaw, companyName, kycRaw] = values;
        if (!firstname || !lastname) { errors.push(`Row ${i + 1}: missing first or last name`); continue; }

        const status = ['active', 'inactive', 'suspended'].includes(statusRaw?.toLowerCase()) ? statusRaw.toLowerCase() : 'active';
        const kyc_completed = kycRaw?.toLowerCase() === 'true' || kycRaw === '1';

        try {
          await apiFetch('/api/customers', {
            method: 'POST',
            body: JSON.stringify({
              firstname,
              middlename: middlename || null,
              lastname,
              email: email || null,
              phone: phone || null,
              category: ['individual', 'business'].includes(category?.toLowerCase()) ? category.toLowerCase() : 'individual',
              status,
              company_name: companyName || null,
              kyc_completed,
              is_active: status === 'active',
            }),
          });
          created++;
        } catch (err) {
          errors.push(`Row ${i + 1} (${firstname} ${lastname}): ${err.message}`);
        }
      }

      this.result = { created, errors };
      this.importing = false;

      if (created > 0) {
        showToast(`Imported ${created} customer(s) successfully.`);
        const table = Alpine.$data(document.querySelector('[x-data="customerTable"]'));
        if (table) await table.loadCustomers();
      }
      if (errors.length > 0) {
        showToast(`${errors.length} row(s) failed. See import result.`, 'warning');
      }
    },

    handleFile(event) {
      this.file   = event.target.files[0] ?? null;
      this.result = null;
    },
  }));

});

// ==========================================================================
// Dashboard Manager - Advanced data visualization and components
// ==========================================================================

import ApexCharts from 'apexcharts';
import {
  REALTIME_DASHBOARD_POLL_MS,
  CHART_RESIZE_DEBOUNCE_MS,
  STAT_ANIMATION_DURATION_MS,
  STAT_ANIMATION_STEPS,
} from '../utils/constants.js';

export class DashboardManager {
  constructor() {
    this.charts = new Map();
    this.intervals = new Set();
    this.timeouts = new Set();
    this.cleanupFns = [];
    this.data = {
      revenue: [],
      users: [],
      orders: [],
      performance: [],
      recentOrders: [],
      salesByLocation: []
    };
    this.currentPeriod = '7d';
    this.init();
  }

  async init() {
    await this.loadDashboardData();

    this.initRevenueChart();
    this.initUserGrowthChart();
    this.initOrderStatusChart();
    this.initStorageChart();
    this.initSalesByLocationChart();
    this.populateRecentOrders();

    this.initInteractiveElements();
    this.initResizeHandler();

    // Set initial view to match active UI state (7D)
    this.updateChartPeriod(this.currentPeriod);
  }

  initResizeHandler() {
    const onResize = () => {
      const t = setTimeout(() => {
        this.charts.forEach(chart => {
          if (typeof chart.updateOptions === 'function') {
            chart.updateOptions({ chart: { width: '100%' } }, false, true);
          }
        });
        this.timeouts.delete(t);
      }, CHART_RESIZE_DEBOUNCE_MS);
      this.timeouts.add(t);
    };
    window.addEventListener('resize', onResize);
    this.cleanupFns.push(() => window.removeEventListener('resize', onResize));

    const onThemeChange = (e) => {
      const theme = e.detail?.theme || 'light';
      this.charts.forEach(chart => {
        if (typeof chart.updateOptions === 'function') {
          chart.updateOptions({ theme: { mode: theme } });
        }
      });
    };
    window.addEventListener('themeChanged', onThemeChange);
    this.cleanupFns.push(() => window.removeEventListener('themeChanged', onThemeChange));
  }

  async loadDashboardData() {
    if (window.dashboardData) {
      this.data.revenue = window.dashboardData.revenue_monthly || [];
      this.data.dailyRevenue = window.dashboardData.revenue_daily || [];
      this.data.users = window.dashboardData.users || [];
      this.data.orders = window.dashboardData.orders || {
        completed: 0, pending: 0, cancelled: 0, processing: 0
      };
      this.data.recentOrders = window.dashboardData.recentOrders || [];
      this.data.salesByLocation = window.dashboardData.salesByLocation || [];
    }
  }

  initRevenueChart() {
    const el = document.getElementById('revenueChart');
    if (!el) return;

    const options = {
      chart: {
        type: 'area',
        height: 320,
        toolbar: { show: false },
        zoom: { enabled: false }
      },
      series: [
        { name: 'Revenue', data: this.data.revenue.map(item => item.revenue) },
        { name: 'Profit', data: this.data.revenue.map(item => item.profit) }
      ],
      xaxis: {
        categories: this.data.revenue.map(item => item.month),
        axisBorder: { show: false }
      },
      yaxis: {
        labels: {
          formatter: value => '$' + value.toLocaleString()
        }
      },
      colors: ['#6366f1', '#10b981'],
      stroke: { curve: 'smooth', width: 2 },
      fill: {
        type: 'gradient',
        gradient: { shadeIntensity: 1, opacityFrom: 0.3, opacityTo: 0.05 }
      },
      dataLabels: { enabled: false },
      legend: { position: 'top' },
      tooltip: {
        y: { formatter: value => '$' + value.toLocaleString() }
      },
      grid: { borderColor: 'rgba(0,0,0,0.08)', strokeDashArray: 4 }
    };

    const chart = new ApexCharts(el, options);
    chart.render();
    this.charts.set('revenue', chart);
  }

  initUserGrowthChart() {
    const el = document.getElementById('userGrowthChart');
    if (!el) return;

    const recent = this.data.users.slice(-7);
    const options = {
      chart: { type: 'bar', height: 280, toolbar: { show: false } },
      series: [{ name: 'New Users', data: recent.map(item => item.newUsers) }],
      xaxis: {
        categories: recent.map(item => `Day ${item.day}`),
        axisBorder: { show: false }
      },
      colors: ['#6366f1'],
      plotOptions: { bar: { borderRadius: 6, columnWidth: '55%' } },
      dataLabels: { enabled: false },
      grid: { borderColor: 'rgba(0,0,0,0.08)', strokeDashArray: 4 }
    };

