        const response = await fetch(url, { headers: reqHeaders, ...otherOptions });
        const text = await response.text();
        const payload = text ? JSON.parse(text) : {};
        if (!response.ok) {
            const msg = payload?.errors ? Object.values(payload.errors).flat().join(' ') : payload?.message || 'Request failed.';
            throw new Error(msg);
        }
        return payload;
    },

    async loadOptions() {
        try {
            const data = await this.apiRequest('/api/inventory/transfers/options');
            this.warehouses = data.warehouses || [];
            this.productOptions = data.products || [];

            // Automatically select default warehouse if not already filtered
            if (!this.warehouseFilter) {
                const defaultWh = this.warehouses.find(w => w.is_default);
                if (defaultWh) {
                    this.warehouseFilter = defaultWh.id.toString();
                }
            }
        } catch (e) { console.error(e); }
    },

    async loadData() {
        this.isLoading = true;
        try {
            const params = new URLSearchParams({ per_page: this.itemsPerPage, page: this.currentPage, sort_by: this.sortField, sort_dir: this.sortDirection });
            if (this.searchQuery) params.set('search', this.searchQuery);
            if (this.warehouseFilter) params.set('warehouse_id', this.warehouseFilter);
            if (this.stockLevelFilter) params.set('stock_level', this.stockLevelFilter);
            const data = await this.apiRequest(`/api/inventory/stocks?${params}`);
            this.items = data.data || [];
            this.stats = data.stats || this.stats;
            this.totalItems = data.meta?.total || 0;
            this.totalPages = data.meta?.last_page || 1;

            // Clear selection on page load
            this.selectedItems = [];
        } catch (e) {
            showToast(e.message, 'error');
        } finally {
            this.isLoading = false;
        }
    },

    // Selection helper methods
    toggleAll(checked) {
      if (checked) {
        this.items.forEach(item => {
          if (!this.selectedItems.includes(String(item.id))) {
            this.selectedItems.push(String(item.id));
          }
        });
      } else {
        const currentIds = this.items.map(item => String(item.id));
        this.selectedItems = this.selectedItems.filter(id => !currentIds.includes(id));
      }
    },

    toggleItem(itemId) {
        if (this.selectedItems.includes(itemId)) {
            this.selectedItems = this.selectedItems.filter(id => id !== itemId);
        } else {
            this.selectedItems = [...this.selectedItems, itemId];
        }
    },

    get paginatedItems() { return this.items; },

    get pageFrom() { return this.totalItems === 0 ? 0 : (this.currentPage - 1) * this.itemsPerPage + 1; },
    get pageTo() { return Math.min(this.currentPage * this.itemsPerPage, this.totalItems); },

    // Standardized visiblePages getter
    get visiblePages() {
        const delta = 2;
        const range = [];
        for (let i = Math.max(2, this.currentPage - delta);
             i <= Math.min(this.totalPages - 1, this.currentPage + delta); i++) {
            range.push(i);
        }
        const result = [];
        if (this.currentPage - delta > 2) result.push(1, '...');
        else result.push(1);
        result.push(...range);
        if (this.currentPage + delta < this.totalPages - 1) result.push('...', this.totalPages);
        else if (this.totalPages > 1) result.push(this.totalPages);
        return result.filter((v, i, a) => a.indexOf(v) === i && (typeof v === 'string' || v <= this.totalPages));
    },

    goToPage(page) {
        if (page >= 1 && page <= this.totalPages) {
            this.currentPage = page;
            this.loadData();
        }
    },

    // CSV Export
    async fetchAllFiltered() {
        const params = new URLSearchParams({ per_page: 1000, sort_by: this.sortField, sort_dir: this.sortDirection });
        if (this.searchQuery) params.set('search', this.searchQuery);
        if (this.warehouseFilter) params.set('warehouse_id', this.warehouseFilter);
        if (this.stockLevelFilter) params.set('stock_level', this.stockLevelFilter);
        const data = await this.apiRequest(`/api/inventory/stocks?${params}`);
        return data.data || [];
    },

    async exportStock(selectedOnly = false) {
        try {
            let exportItems = [];
            if (selectedOnly) {
                exportItems = this.items.filter(item => this.selectedItems.includes(item.id));
                if (exportItems.length === 0) {
                    showToast('No items selected for export.', 'warning');
                    return;
                }
            } else {
                exportItems = await this.fetchAllFiltered();
            }

            const headers = ['Product Name', 'SKU', 'Warehouse', 'Quantity', 'Reserved', 'Dispatched', 'Delivered', 'In Transit', 'Bad Qty', 'Alert Level', 'Status'];
            const rows = exportItems.map(item => {
                const qty = parseFloat(item.quantity || 0);
                const reserved = parseFloat(item.reserved_qty || 0);
                const dispatched = parseFloat(item.dispatched_qty || 0);
                const delivered = parseFloat(item.delivered_qty || 0);
                const inTransit = parseFloat(item.in_transit_qty || 0);
                const damaged = parseFloat(item.damaged_qty || 0);
                const alert = parseFloat(item.product?.alert_quantity || 0);
                let status = 'In Stock';
                if (qty <= 0) status = 'Out of Stock';
                else if (qty <= alert) status = 'Low Stock';

                return [
                    item.product?.name || '',
                    item.product?.sku || '',
                    item.warehouse?.name || '',
                    qty,
                    reserved,
                    dispatched,
                    delivered,
                    inTransit,
                    damaged,
                    alert,
                    status
                ];
            });

            const csvEscape = val => `"${String(val ?? '').replace(/"/g, '""')}"`;
            const csvContent = [headers, ...rows].map(r => r.map(csvEscape).join(',')).join('\n');

            const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.download = `stock-levels-export.csv`;
            document.body.appendChild(link);
            link.click();
            URL.revokeObjectURL(link.href);
            document.body.removeChild(link);

            showToast(`Exported ${exportItems.length} record(s) successfully.`);
        } catch (e) {
            showToast('Export failed: ' + e.message, 'danger');
        }
    },

    openAdjustModal(item) {
        if (!item) {
            this.isEditing = false;
            this.adjustForm = {
                productId: '',
                warehouseId: '',
                productName: '',
                warehouseName: '',
                currentQty: 0,
                newQty: 0,
                currentDamagedQty: 0,
                newDamagedQty: 0,
            };
        } else {
            this.isEditing = true;
            this.adjustForm = {
                productId: item.product_id,
                warehouseId: item.warehouse_id,
                productName: (item.product?.name || '') + (item.product?.sku ? ` (${item.product.sku})` : ''),
                warehouseName: item.warehouse?.name || '',
                currentQty: parseFloat(item.quantity || 0),
                newQty: parseFloat(item.quantity || 0),
                currentDamagedQty: parseFloat(item.damaged_qty || 0),
                newDamagedQty: parseFloat(item.damaged_qty || 0),
            };
        }
        this.modalInstance?.show();
    },

    async fetchCurrentStock() {
        const prodId = this.adjustForm.productId;
        const whId = this.adjustForm.warehouseId;
        if (!prodId || !whId) {
            this.adjustForm.currentQty = 0;
            this.adjustForm.currentDamagedQty = 0;
            return;
        }
        try {
            const data = await this.apiRequest(`/api/inventory/stocks/show?product_id=${prodId}&warehouse_id=${whId}`);
            this.adjustForm.currentQty = parseFloat(data.data?.quantity || 0);
            this.adjustForm.currentDamagedQty = parseFloat(data.data?.damaged_qty || 0);
        } catch (e) {
            this.adjustForm.currentQty = 0;
            this.adjustForm.currentDamagedQty = 0;
        }
    },

    async saveAdjustment() {
        if (!this.adjustForm.productId || !this.adjustForm.warehouseId) {
            showToast('Please select both product and warehouse.', 'error');
            return;
        }
        if (this.adjustForm.newQty === undefined || this.adjustForm.newQty === null || parseFloat(this.adjustForm.newQty) < 0) {
            showToast('Please enter a valid non-negative new quantity.', 'error');
            return;
        }
        if (this.adjustForm.newDamagedQty === undefined || this.adjustForm.newDamagedQty === null || parseFloat(this.adjustForm.newDamagedQty) < 0) {
            showToast('Please enter a valid non-negative bad quantity.', 'error');
            return;
        }
        this.saving = true;
        try {
            await this.apiRequest('/api/inventory/stocks/set', {
                method: 'POST',
                body: JSON.stringify({
                    product_id: this.adjustForm.productId,
                    warehouse_id: this.adjustForm.warehouseId,
                    quantity: this.adjustForm.newQty,
                    damaged_qty: this.adjustForm.newDamagedQty,
                }),
            });
            showToast('Stock level updated successfully.', 'success');
            this.modalInstance?.hide();
            await this.loadData();
        } catch (e) {
            showToast(e.message, 'error');
        } finally {
            this.saving = false;
        }
    },
});

import Alpine from 'alpinejs';
import { Modal } from 'bootstrap';
import Swal from 'sweetalert2';

function showToast(message, type = 'success') {
    const container = document.getElementById('toast-container');
    if (!container) return;
    const id = 'toast-' + Date.now();
    const iconMap = {
        success: 'bi-check-circle-fill',
        danger: 'bi-x-circle-fill',
        warning: 'bi-exclamation-triangle-fill',
        error: 'bi-x-circle-fill'
    };
    const el = document.createElement('div');
    el.id = id;
    el.className = `toast align-items-center text-bg-${type === 'error' || type === 'danger' ? 'danger' : type} border-0 show mb-2`;
    el.setAttribute('role', 'alert');
    el.innerHTML = `<div class="d-flex"><div class="toast-body"><i class="bi ${iconMap[type] ?? 'bi-info-circle-fill'} me-2"></i><span></span></div><button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast"></button></div>`;
    el.querySelector('.toast-body span').textContent = message;
    container.appendChild(el);
    setTimeout(() => el.remove(), 4000);
}

async function confirmAction({ title, text, confirmText = 'Confirm', icon = 'warning' }) {
    const result = await Swal.fire({
        title,
        text,
        icon,
        showCancelButton: true,
        confirmButtonText: confirmText,
        cancelButtonText: 'Cancel',
        confirmButtonColor: icon === 'warning' || icon === 'danger' ? '#dc3545' : '#0d6efd',
        reverseButtons: true,
        focusCancel: true
    });
    return result.isConfirmed;
}

export default () => ({
    items: [],
    stats: { total: 0, draft: 0, pending: 0, received: 0 },
    warehouses: [],
    products: [],
    isLoading: false,
    saving: false,
    isEditing: false,
    searchQuery: '',
    statusFilter: '',
    currentPage: 1,
    itemsPerPage: 25,
    totalItems: 0,
    totalPages: 1,
    modalInstance: null,
    form: { id: null, from_warehouse_id: '', to_warehouse_id: '', items: [{ product_id: '', quantity: 1 }] },
    warehouseStocks: {},

    // Selection state
    selectedItems: [],

    async init() {
        await this.loadOptions();
        await this.loadData();
        const modalEl = document.getElementById('transferModal');
        if (modalEl) {
            this.modalInstance = Modal.getOrCreateInstance(modalEl);
            modalEl.addEventListener('hidden.bs.modal', () => this.resetForm());
        }
    },

    async apiRequest(url, options = {}) {
        const { headers, ...rest } = options;
        const csrfToken = document.querySelector('meta[name="csrf-token"]').content;
        const reqHeaders = { 'X-CSRF-TOKEN': csrfToken, 'X-Requested-With': 'XMLHttpRequest', 'Accept': 'application/json', ...(headers || {}) };
        if (options.body && !(options.body instanceof FormData)) reqHeaders['Content-Type'] = 'application/json';
        const response = await fetch(url, { headers: reqHeaders, ...rest });
        const text = await response.text();
        const payload = text ? JSON.parse(text) : {};
        if (!response.ok) {
            const msg = payload?.errors ? Object.values(payload.errors).flat().join(' ') : payload?.message || 'Request failed.';
            throw new Error(msg);
        }
        return payload;
    },

    async loadOptions() {
        try {
            const data = await this.apiRequest('/api/inventory/transfers/options');
            this.warehouses = data.warehouses || [];
            this.products = data.products || [];
        } catch (e) { console.error(e); }
    },

    async loadData() {
        this.isLoading = true;
        try {
            const params = new URLSearchParams({ per_page: this.itemsPerPage, page: this.currentPage });
            if (this.searchQuery) params.set('search', this.searchQuery);
            if (this.statusFilter) params.set('status', this.statusFilter);
            const data = await this.apiRequest(`/api/inventory/transfers?${params}`);
            this.items = data.data || [];
            this.stats = data.stats || this.stats;
            this.totalItems = data.meta?.total || 0;
            this.totalPages = data.meta?.last_page || 1;

            // Clear selection on page load
            this.selectedItems = [];
        } catch (e) {
            showToast(e.message, 'error');
        } finally {
            this.isLoading = false;
        }
    },

    // Selection helper methods
    toggleAll(checked) {
      if (checked) {
        this.items.forEach(item => {
          if (!this.selectedItems.includes(String(item.id))) {
            this.selectedItems.push(String(item.id));
          }
        });
      } else {
        const currentIds = this.items.map(item => String(item.id));
        this.selectedItems = this.selectedItems.filter(id => !currentIds.includes(id));
      }
    },

    toggleItem(itemId) {
        if (this.selectedItems.includes(itemId)) {
            this.selectedItems = this.selectedItems.filter(id => id !== itemId);
        } else {
            this.selectedItems = [...this.selectedItems, itemId];
        }
    },

    get paginatedItems() { return this.items; },
    get pageFrom() { return this.totalItems === 0 ? 0 : (this.currentPage - 1) * this.itemsPerPage + 1; },
    get pageTo() { return Math.min(this.currentPage * this.itemsPerPage, this.totalItems); },

    // Standardized visiblePages getter
    get visiblePages() {
        const delta = 2;
        const range = [];
        for (let i = Math.max(2, this.currentPage - delta);
             i <= Math.min(this.totalPages - 1, this.currentPage + delta); i++) {
            range.push(i);
        }
        const result = [];
        if (this.currentPage - delta > 2) result.push(1, '...');
        else result.push(1);
        result.push(...range);
        if (this.currentPage + delta < this.totalPages - 1) result.push('...', this.totalPages);
        else if (this.totalPages > 1) result.push(this.totalPages);
        return result.filter((v, i, a) => a.indexOf(v) === i && (typeof v === 'string' || v <= this.totalPages));
    },

    goToPage(page) {
        if (page >= 1 && page <= this.totalPages) {
            this.currentPage = page;
            this.loadData();
        }
    },

    async fetchWarehouseStocks() {
        const fromWarehouseId = this.form.from_warehouse_id;
        if (!fromWarehouseId) {
            this.warehouseStocks = {};
            return;
        }
        try {
            const data = await this.apiRequest(`/api/inventory/stocks?warehouse_id=${fromWarehouseId}&per_page=1000`);
            const stocks = {};
            if (data.data) {
                data.data.forEach(stock => {
                    stocks[stock.product_id] = Math.max(0, parseFloat(stock.quantity) - parseFloat(stock.reserved_qty));
                });
            }
            this.warehouseStocks = stocks;
        } catch (e) {
            console.error('Failed to fetch warehouse stocks:', e);
            this.warehouseStocks = {};
        }
    },

    getProductStock(productId) {
        if (!productId) return 0;
        return this.warehouseStocks[productId] || 0;
    },

    getProductRemainingStock(item) {
        if (!item.product_id) return 0;
        const currentStock = this.getProductStock(item.product_id);
        const qtyToTransfer = parseFloat(item.quantity) || 0;
        return currentStock - qtyToTransfer;
    },

    formatQty(value) {
        const num = parseFloat(value);
        if (isNaN(num)) return '0';
        return num % 1 === 0 ? num.toString() : num.toFixed(2);
    },

    resetForm() {
        this.isEditing = false;
        this.form = { id: null, from_warehouse_id: '', to_warehouse_id: '', items: [{ product_id: '', quantity: 1 }] };
        this.warehouseStocks = {};
    },

    openCreateModal() { this.resetForm(); this.modalInstance?.show(); },

    async editItem(item) {
        this.isEditing = true;
        this.form = {
            id: item.id,
            from_warehouse_id: item.from_warehouse_id,
            to_warehouse_id: item.to_warehouse_id,
            items: (item.items || []).map(i => ({ product_id: i.product_id, quantity: i.quantity })),
        };
        if (this.form.items.length === 0) this.form.items = [{ product_id: '', quantity: 1 }];
        await this.fetchWarehouseStocks();
        this.modalInstance?.show();
    },

    addItem() { this.form.items.push({ product_id: '', quantity: 1 }); },
    removeItem(index) { if (this.form.items.length > 1) this.form.items.splice(index, 1); },

    async saveItem() {
        if (!this.form.from_warehouse_id || !this.form.to_warehouse_id) {
            showToast('Please select source and destination warehouses.', 'error');
            return;
        }
        if (this.form.from_warehouse_id == this.form.to_warehouse_id) {
            showToast('Source and Destination warehouses must be different.', 'error');
            return;
        }
        const invalid = this.form.items.some(i => !i.product_id || !i.quantity || parseFloat(i.quantity) <= 0);
        if (invalid) {
            showToast('Please select a product and valid quantity for all items.', 'error');
            return;
        }

        this.saving = true;
        try {
            const payload = { from_warehouse_id: this.form.from_warehouse_id, to_warehouse_id: this.form.to_warehouse_id, items: this.form.items };
            if (this.form.id) {
                await this.apiRequest(`/api/inventory/transfers/${this.form.id}`, { method: 'PUT', body: JSON.stringify(payload) });
                showToast('Transfer updated successfully.', 'success');
            } else {
                await this.apiRequest('/api/inventory/transfers', { method: 'POST', body: JSON.stringify(payload) });
                showToast('Transfer created successfully.', 'success');
            }
            this.modalInstance?.hide();
            await this.loadData();
