import Alpine from 'alpinejs';
import ApexCharts from 'apexcharts';
import { Modal } from 'bootstrap';
import Swal from 'sweetalert2';

function getCsrfToken() {
  return document.querySelector('meta[name="csrf-token"]')?.content ?? '';
}

async function apiFetch(url, options = {}) {
  const { headers, ...otherOptions } = options;
  const res = await fetch(url, {
    headers: {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      'X-CSRF-TOKEN': getCsrfToken(),
      ...(headers || {}),
    },
    ...otherOptions,
  });

  const text = await res.text();
  const data = text ? JSON.parse(text) : {};

  if (!res.ok) {
    const validation = data?.errors ? Object.values(data.errors).flat().join(' ') : '';
    throw new Error(validation || data?.message || data?.error || 'Request failed');
  }

  return data;
}

function getModal(selector) {
  const element = document.querySelector(selector);
  return element ? Modal.getOrCreateInstance(element) : null;
}

function showToast(message, type = 'success') {
  const container = document.getElementById('toast-container');
  if (!container) return;

  const iconMap = {
    success: 'bi-check-circle-fill',
    danger:  'bi-x-circle-fill',
    warning: 'bi-exclamation-triangle-fill',
    info:    'bi-info-circle-fill',
  };

  const el = document.createElement('div');
  el.className = `toast align-items-center text-bg-${type} border-0 show mb-2`;
  el.setAttribute('role', 'alert');
  el.innerHTML = `
    <div class="d-flex">
      <div class="toast-body">
        <i class="bi ${iconMap[type] ?? 'bi-info-circle-fill'} me-2"></i><span></span>
      </div>
      <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast"></button>
    </div>`;
  el.querySelector('.toast-body span').textContent = message;
  container.appendChild(el);
  setTimeout(() => el.remove(), 4000);
}

async function confirmDelete({ title, text, confirmButtonText = 'Yes, delete it' }) {
  const result = await Swal.fire({
    title,
    text,
    icon: 'warning',
    showCancelButton: true,
    confirmButtonText,
    cancelButtonText: 'Cancel',
    confirmButtonColor: '#dc3545',
    reverseButtons: true,
    focusCancel: true,
  });

  return result.isConfirmed;
}

function formatDate(value) {
  return value ? new Date(value).toLocaleDateString() : 'N/A';
}

function formatDateTime(value) {
  if (!value) return 'N/A';

  return new Date(value).toLocaleString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

function csvEscape(value) {
  return `"${String(value ?? '').replace(/"/g, '""')}"`;
}

function downloadBlob(filename, content, type) {
  const blob = new Blob([content], { type });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  URL.revokeObjectURL(link.href);
  document.body.removeChild(link);
}

function parseCsvLine(line) {
  const values = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const next = line[i + 1];

    if (char === '"' && inQuotes && next === '"') {
      current += '"';
      i++;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      values.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }

  values.push(current.trim());
  return values;
}

function endpointFor(type) {
  return type === 'roles' ? '/api/roles' : '/api/permissions';
}

function permissionGroupFor(name) {
  let prefix = String(name ?? '').split(/[-.]/)[0] || 'other';

  if (name === 'view_all_order') prefix = 'orders';
  if (name === 'view-all-data') prefix = 'view-all-data';
  if (prefix === 'bulkuser') prefix = 'user';
  if (prefix === 'audit-log') prefix = 'audit';

  const label = getEntityLabel(name);

  const icons = {
    orders: 'cart', invoices: 'receipt', payments: 'credit-card', refunds: 'arrow-return-left', returns: 'box-arrow-in-down-left',
    customer: 'people', customeraddress: 'geo-alt',
    product: 'box', category: 'tags', brand: 'award', catalog: 'collection', productattribute: 'list-ul', hsncode: 'upc-scan', taxrate: 'percent', unitofmeasure: 'rulers',
    warehouse: 'building', inventoryadjustment: 'sliders', stockmanagement: 'boxes', stocktransfer: 'arrow-left-right',
    coupon: 'ticket', promotions: 'megaphone',
    chat: 'chat', messages: 'envelope', calendar: 'calendar', files: 'folder', forms: 'ui-radios', security: 'shield-lock', help: 'question-circle',
    village: 'pin-map', shipping: 'truck', role: 'shield-shaded', permission: 'key', user: 'person-badge', dashboard: 'speedometer2', analytics: 'graph-up', reports: 'file-earmark-bar-graph', settings: 'gear', audit: 'journal-text',
    'view-all-data': 'globe'
  };

  return { 
    key: prefix, 
    label: label, 
    icon: icons[prefix] || 'grid', 
    order: 99 
  };
}

function permissionActionLabel(name) {
  if (name === 'view_all_order') return 'View All';
  if (name === 'bulkuser-manage') return 'Bulk Manage';
  if (name === 'bulkuser-view') return 'Bulk View';

  const parts = String(name ?? '').split(/[-.]/);
  if (parts.length <= 1) return String(name ?? '');

  return parts.slice(1)
    .map(part => part.charAt(0).toUpperCase() + part.slice(1).replace(/_/g, ' '))
    .join(' ');
}

function getEntityLabel(name) {
  let prefix = String(name ?? '').split(/[-.]/)[0] || 'other';
  if (name === 'view_all_order') prefix = 'orders';
  if (name === 'view-all-data') prefix = 'view-all-data';
  if (prefix === 'bulkuser') prefix = 'user';
  if (prefix === 'audit-log') prefix = 'audit';

  const labels = {
    brand: 'Brands', catalog: 'Catalogs', category: 'Categories', productattribute: 'Product Attributes',
    hsncode: 'HSN Codes', taxrate: 'Tax Rates', unitofmeasure: 'Units of Measure', product: 'Products',
    warehouse: 'Warehouses', inventoryadjustment: 'Inventory Adjustments', stockmanagement: 'Stock Management',
    stocktransfer: 'Stock Transfers', orders: 'Orders', invoices: 'Invoices', payments: 'Payments',
    refunds: 'Refunds', returns: 'Returns', customer: 'Customers', customeraddress: 'Customer Addresses',
    coupon: 'Coupons', promotions: 'Promotions', village: 'Villages', shipping: 'Shipping', role: 'Roles',
    permission: 'Permissions', user: 'Users', audit: 'Audit Logs', dashboard: 'Dashboard', 'view-all-data': 'Global Data Visibility',
    chat: 'Team Chat', messages: 'Messages', calendar: 'Calendar', files: 'Files', forms: 'Forms', security: 'Security', help: 'Help & Support',
    analytics: 'Analytics', reports: 'Reports', settings: 'Settings'
  };
  return labels[prefix] || (prefix.charAt(0).toUpperCase() + prefix.slice(1));
}

function groupPermissions(permissions) {
  const groups = new Map();

  [...permissions]
    .sort((a, b) => String(a.name).localeCompare(String(b.name)))
    .forEach(permission => {
      const group = permissionGroupFor(permission.name);
      if (!groups.has(group.key)) {
        groups.set(group.key, {
          ...group,
          items: [],
          subGroups: [],
        });
      }

      const permObj = {
        ...permission,
        actionLabel: permissionActionLabel(permission.name),
      };

      const groupData = groups.get(group.key);
      groupData.items.push(permObj);

      const subLabel = getEntityLabel(permission.name);
      let subGroup = groupData.subGroups.find(s => s.label === subLabel);
      if (!subGroup) {
        subGroup = { label: subLabel, items: [] };
        groupData.subGroups.push(subGroup);
      }
      subGroup.items.push(permObj);
    });

  return [...groups.values()].sort((a, b) => a.order - b.order || a.label.localeCompare(b.label));
}

document.addEventListener('alpine:init', () => {
  Alpine.data('rolesPermissionsTable', () => ({
    activeTab: 'roles',
    roles: [],
    permissions: [],
    selectedItems: [],
    searchQuery: '',
    statusFilter: '',
    guardFilter: '',
    sortField: 'name',
    sortDirection: 'asc',
    currentPage: 1,
    totalPages: 1,
    totalItems: 0,
    itemsPerPage: 10,
    isLoading: false,
    activityPeriod: 7,
    charts: {},
    _resizeHandler: null,
    _themeObserver: null,

    async init() {
      await Promise.all([this.loadRoles(), this.loadPermissions()]);
      this.$nextTick(() => {
        this.initCharts();
        this.initResizeHandler();
      });
      window.addEventListener('pagehide', () => this.destroy(), { once: true });
      this._themeObserver = new MutationObserver(() => {
        this.$nextTick(() => {
          this.clearExistingCharts();
          this.initCharts();
        });
      });
      this._themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ['data-bs-theme'],
      });
    },

    destroy() {
      if (this._resizeHandler) {
        window.removeEventListener('resize', this._resizeHandler);
        this._resizeHandler = null;
      }
      if (this._themeObserver) {
        this._themeObserver.disconnect();
        this._themeObserver = null;
      }
      this.clearExistingCharts();
    },

    initResizeHandler() {
      this._resizeHandler = () => {
        Object.values(this.charts).forEach(chart => {
          if (chart && typeof chart.updateOptions === 'function') {
            chart.updateOptions({ chart: { width: '100%' } }, false, true);
          }
        });
      };
      window.addEventListener('resize', this._resizeHandler);
    },

    clearExistingCharts() {
      Object.values(this.charts).forEach(chart => {
        if (chart && typeof chart.destroy === 'function') chart.destroy();
      });
      this.charts = {};
      document.querySelector('#accessCoverageChart')?.removeAttribute('data-chart-initialized');
      document.querySelector('#guardDistributionChart')?.removeAttribute('data-chart-initialized');
    },

    params(overrides = {}) {
      const params = new URLSearchParams({
        page: overrides.page ?? this.currentPage,
        per_page: overrides.per_page ?? this.itemsPerPage,
        sort_by: this.sortField,
        sort_dir: this.sortDirection,
      });
      if (this.searchQuery) params.set('search', this.searchQuery);
      if (this.guardFilter) params.set('guard_name', this.guardFilter);
      if (!this.statusFilter) params.set('deleted', 'with');
      if (this.statusFilter === 'deleted') params.set('deleted', 'only');
      if (this.statusFilter === 'active') params.set('deleted', 'without');
      return params;
    },

    async loadRoles() {
      if (this.activeTab === 'roles') this.isLoading = true;
      try {
        const data = await apiFetch(`/api/roles?${this.params()}`);
        this.roles = (data.data ?? []).map(item => this.mapItem(item));
        if (this.activeTab === 'roles') this.applyPagination(data);
      } catch (err) {
        showToast(`Failed to load roles: ${err.message}`, 'danger');
      } finally {
        this.isLoading = false;
      }
    },

    async loadPermissions() {
      if (this.activeTab === 'permissions') this.isLoading = true;
      try {
        const data = await apiFetch(`/api/permissions?${this.params()}`);
        this.permissions = (data.data ?? []).map(item => this.mapItem(item));
        if (this.activeTab === 'permissions') this.applyPagination(data);
      } catch (err) {
        showToast(`Failed to load permissions: ${err.message}`, 'danger');
      } finally {
        this.isLoading = false;
      }
    },

    async loadCurrent() {
      await (this.activeTab === 'roles' ? this.loadRoles() : this.loadPermissions());
      this.$nextTick(() => {
        this.clearExistingCharts();
        this.initCharts();
      });
    },

    applyPagination(data) {
      this.totalItems = data.total ?? this.currentItems.length;
      this.totalPages = data.last_page ?? 1;
      this.currentPage = data.current_page ?? 1;
    },

    mapItem(item) {
      return {
        ...item,
        isDeleted: Boolean(item.deleted_at),
        updatedAt: formatDate(item.updated_at),
        updatedAtDateTime: formatDateTime(item.updated_at),
        createdAt: formatDate(item.created_at),
        createdAtDateTime: formatDateTime(item.created_at),
        permissions: item.permissions ?? [],
        roles: item.roles ?? [],
        permissions_count: item.permissions_count ?? item.permissions?.length ?? 0,
        roles_count: item.roles_count ?? item.roles?.length ?? 0,
        permissionGroups: groupPermissions(item.permissions ?? []),
        permissionGroup: permissionGroupFor(item.name),
        permissionActionLabel: permissionActionLabel(item.name),
      };
    },

    switchTab(tab) {
      this.activeTab = tab;
      this.currentPage = 1;
      this.selectedItems = [];
      this.loadCurrent();
    },

    filterItems() {
      this.currentPage = 1;

      this.loadCurrent();
    },

    sortBy(field) {
      if (this.sortField === field) {
        this.sortDirection = this.sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        this.sortField = field;
        this.sortDirection = 'asc';
      }
      this.loadCurrent();
    },

    get currentItems() {
      return this.activeTab === 'roles' ? this.roles : this.permissions;
    },

    get selectedRows() {
      return this.currentItems.filter(item => this.selectedItems.includes(item.id));
    },

    get hasSelectedDeletedItems() {
      return this.selectedRows.some(item => item.isDeleted);
    },

    get hasSelectedActiveItems() {
      return this.selectedRows.some(item => !item.isDeleted);
    },

    get pageFrom() {
      if (this.totalItems === 0) return 0;
      return (this.currentPage - 1) * this.itemsPerPage + 1;
    },

    get pageTo() {
      return Math.min(this.currentPage * this.itemsPerPage, this.totalItems);
    },

    get visiblePages() {
      const delta = 2;
      const range = [];
      for (let i = Math.max(2, this.currentPage - delta); i <= Math.min(this.totalPages - 1, this.currentPage + delta); i++) {
        range.push(i);
      }
      const result = [];
      if (this.currentPage - delta > 2) result.push(1, '...');
      else result.push(1);
      result.push(...range);
      if (this.currentPage + delta < this.totalPages - 1) result.push('...', this.totalPages);
      else if (this.totalPages > 1) result.push(this.totalPages);
      return result.filter((value, index, all) => all.indexOf(value) === index && (typeof value === 'string' || value <= this.totalPages));
    },

    goToPage(page) {
      if (page >= 1 && page <= this.totalPages) {
        this.currentPage = page;
        this.loadCurrent();
      }
    },

    toggleAll(checked) {
      if (checked) {
        this.currentItems.forEach(item => {
          if (!this.selectedItems.includes(String(item.id))) {
            this.selectedItems.push(String(item.id));
          }
        });
      } else {
        const currentIds = this.currentItems.map(item => String(item.id));
        this.selectedItems = this.selectedItems.filter(id => !currentIds.includes(id));
      }
    },

    toggleItem(itemId) {
      if (this.selectedItems.includes(itemId)) {
        this.selectedItems = this.selectedItems.filter(id => id !== itemId);
      } else {
        this.selectedItems = [...this.selectedItems, itemId];
      }
    },

    openCreate() {
      const form = Alpine.$data(document.querySelector('[x-data="accessForm"]'));
      if (!form) return;
      form.resetForm(this.activeTab);
      getModal('#accessModal')?.show();
    },

    editItem(item) {
      if (item.isDeleted) {
        showToast('Restore this item before editing.', 'warning');
        return;
      }
      const form = Alpine.$data(document.querySelector('[x-data="accessForm"]'));
      if (!form) return;
      form.editItem(this.activeTab, item);
      getModal('#accessModal')?.show();
    },

    async viewItem(item) {
      const profile = Alpine.$data(document.querySelector('[x-data="accessProfile"]'));
      if (!profile) return;
      profile.loading = true;
      profile.type = this.activeTab;
      profile.item = item;
      getModal('#accessViewModal')?.show();
      try {
        const data = await apiFetch(`${endpointFor(this.activeTab)}/${item.id}`);
        profile.item = this.mapItem(data.data ?? data);
      } catch (err) {
        showToast(`Could not load details: ${err.message}`, 'warning');
      } finally {
        profile.loading = false;
      }
    },

    async deleteItem(item) {
      const confirmed = await confirmDelete({
        title: `Temporarily delete ${this.singularLabel}?`,
        text: `Do you want to move ${item.name} to deleted ${this.activeTab}? You can restore it later.`,
        confirmButtonText: 'Yes, delete it',
      });
      if (!confirmed) return;

      try {
        const res = await apiFetch(`${endpointFor(this.activeTab)}/${item.id}`, { method: 'DELETE' });
        showToast(res.message || `${item.name} deleted successfully.`);
        await this.loadCurrent();
      } catch (err) {
        showToast(`Failed to delete ${item.name}: ${err.message}`, 'danger');
      }
    },

    async restoreItem(item) {
      try {
        const res = await apiFetch(`${endpointFor(this.activeTab)}/${item.id}/restore`, { method: 'PATCH' });
        showToast(res.message || `${item.name} restored successfully.`);
        await this.loadCurrent();
      } catch (err) {
        showToast(`Failed to restore ${item.name}: ${err.message}`, 'danger');
      }
    },

    async forceDeleteItem(item) {
      const confirmed = await confirmDelete({
        title: `Permanently delete ${this.singularLabel}?`,
        text: `This will permanently delete ${item.name}. This action cannot be undone.`,
        confirmButtonText: 'Yes, permanently delete',
      });
      if (!confirmed) return;

      try {
        const res = await apiFetch(`${endpointFor(this.activeTab)}/${item.id}/force`, { method: 'DELETE' });
        showToast(res.message || `${item.name} permanently deleted successfully.`);
        await this.loadCurrent();
      } catch (err) {
        showToast(`Failed to permanently delete ${item.name}: ${err.message}`, 'danger');
      }
    },

    async bulkAction(action) {
      if (this.selectedItems.length === 0) {
        showToast('Please select items first.', 'warning');
        return;
      }

      if (action === 'delete' || action === 'force-delete') {
        const confirmed = await confirmDelete({
          title: action === 'delete' ? 'Temporarily delete selected items?' : 'Permanently delete selected items?',
          text: action === 'delete'
            ? `Do you want to move ${this.selectedItems.length} selected item(s) to deleted records?`
            : `This will permanently delete ${this.selectedItems.length} selected item(s). This action cannot be undone.`,
          confirmButtonText: action === 'delete' ? 'Yes, delete items' : 'Yes, permanently delete',
        });
        if (!confirmed) return;
      }

      const selected = [...this.selectedRows];
      let completed = 0;
      let failed = 0;

      for (const item of selected) {
        try {
          if (action === 'delete') await apiFetch(`${endpointFor(this.activeTab)}/${item.id}`, { method: 'DELETE' });
          if (action === 'restore') await apiFetch(`${endpointFor(this.activeTab)}/${item.id}/restore`, { method: 'PATCH' });
          if (action === 'force-delete') await apiFetch(`${endpointFor(this.activeTab)}/${item.id}/force`, { method: 'DELETE' });
          completed++;
        } catch {
          failed++;
        }
      }

      this.selectedItems = [];
      await this.loadCurrent();
      showToast(`${completed} item(s) processed${failed ? `, ${failed} failed` : ''}.`, failed ? 'warning' : 'success');
    },

    async exportItems() {
      try {
        const first = await apiFetch(`${endpointFor(this.activeTab)}?${this.params({ page: 1, per_page: 500 })}`);
        const rows = (first.data ?? []).map(item => this.mapItem(item));
        for (let page = 2; page <= (first.last_page ?? 1); page++) {
          const data = await apiFetch(`${endpointFor(this.activeTab)}?${this.params({ page, per_page: 500 })}`);
          rows.push(...(data.data ?? []).map(item => this.mapItem(item)));
        }

        const headers = this.activeTab === 'roles'
          ? ['ID', 'Name', 'Guard', 'Permissions', 'Status', 'Created', 'Updated']
          : ['ID', 'Name', 'Guard', 'Roles', 'Status', 'Created', 'Updated'];
        const csvRows = rows.map(item => [
          item.id,
          item.name,
          item.guard_name,
          this.activeTab === 'roles' ? item.permissions.map(p => p.name).join('|') : item.roles.map(r => r.name).join('|'),
          item.isDeleted ? 'deleted' : 'active',
          item.createdAtDateTime,
          item.updatedAtDateTime,
        ]);
        const csv = [headers, ...csvRows].map(row => row.map(csvEscape).join(',')).join('\n');
        downloadBlob(`${this.activeTab}-export.csv`, csv, 'text/csv;charset=utf-8;');
        showToast(`Exported ${rows.length} ${this.activeTab}.`);
      } catch (err) {
        showToast(`Export failed: ${err.message}`, 'danger');
      }
    },

    get singularLabel() {
      return this.activeTab === 'roles' ? 'role' : 'permission';
    },

    get roleStats() {
      return {
        total: this.activeTab === 'roles' ? this.totalItems : this.roles.length,
      };
    },

    get permissionStats() {
      return {
        total: this.activeTab === 'permissions' ? this.totalItems : this.permissions.length,
      };
    },

    get assignmentCount() {
      return this.roles.reduce((total, role) => total + Number(role.permissions_count || 0), 0);
    },

    get deletedCount() {
      return this.currentItems.filter(item => item.isDeleted).length;
    },

    get topRoles() {
      return [...this.roles]
        .sort((a, b) => Number(b.permissions_count || 0) - Number(a.permissions_count || 0))
        .slice(0, 5);
    },

    get recentActivities() {
      return this.currentItems.slice(0, 5).map((item, index) => ({
        id: `${this.activeTab}-${item.id}-${index}`,
        name: item.name,
        action: item.isDeleted ? 'was deleted' : 'was updated',
        time: `Date & time: ${item.updatedAtDateTime}`,
        type: item.isDeleted ? 'deleted' : 'updated',
        icon: item.isDeleted ? 'trash' : (this.activeTab === 'roles' ? 'shield-check' : 'key'),
        details: `${item.guard_name} guard · ${this.activeTab === 'roles' ? `${item.permissions_count || 0} permissions` : `${item.roles_count || 0} roles`}`,
      }));
    },

    get systemAlerts() {
      const alerts = [];
      if (this.roles.length === 0) {
        alerts.push({ id: 1, title: 'No Roles', message: 'No roles found. Add your first role.', type: 'info', time: 'Just now' });
      }
      if (this.permissions.length === 0) {
        alerts.push({ id: 2, title: 'No Permissions', message: 'No permissions found. Add your first permission.', type: 'warning', time: 'Just now' });
      }
      return alerts;
    },

    setActivityPeriod(days) {
      this.activityPeriod = Number(days);
      this.$nextTick(() => {
        this.clearExistingCharts();
        this.initCharts();
      });
    },

    initCharts() {
      this.initCoverageChart();
      this.initGuardChart();
    },

    initCoverageChart() {
      const el = document.querySelector('#accessCoverageChart');
      if (!el || el.hasAttribute('data-chart-initialized')) return;
      el.setAttribute('data-chart-initialized', 'true');

      const period = Number(this.activityPeriod) || 7;
      const labels = [];
      const roleCounts = [];
      const permissionCounts = [];
      const now = new Date();
      for (let i = period - 1; i >= 0; i--) {
        const date = new Date(now);
        date.setDate(date.getDate() - i);
        labels.push(date.toLocaleDateString('en', period <= 7 ? { weekday: 'short' } : { month: 'short', day: 'numeric' }));
        roleCounts.push(this.roles.filter(role => new Date(role.created_at).toDateString() === date.toDateString()).length);
        permissionCounts.push(this.permissions.filter(permission => new Date(permission.created_at).toDateString() === date.toDateString()).length);
      }

      this.charts.coverage = new ApexCharts(el, {
        series: [
          { name: 'Roles', data: roleCounts },
          { name: 'Permissions', data: permissionCounts },
        ],
        chart: { type: 'bar', height: 250, width: '100%', toolbar: { show: false }, zoom: { enabled: false } },
        colors: ['#6366f1', '#10b981'],
        plotOptions: { bar: { borderRadius: 4, columnWidth: '50%' } },
        xaxis: { categories: labels, axisBorder: { show: false }, axisTicks: { show: false }, labels: { style: { fontSize: '12px', colors: '#64748b' } } },
        yaxis: { show: false },
        grid: { show: false },
        dataLabels: { enabled: false },
        tooltip: { theme: document.documentElement.getAttribute('data-bs-theme') === 'dark' ? 'dark' : 'light' },
      });
      this.charts.coverage.render();
    },

    initGuardChart() {
      const el = document.querySelector('#guardDistributionChart');
      if (!el || el.hasAttribute('data-chart-initialized')) return;
      el.setAttribute('data-chart-initialized', 'true');

      const counts = [...this.roles, ...this.permissions].reduce((acc, item) => {
        const guard = item.guard_name || 'web';
        acc[guard] = (acc[guard] || 0) + 1;
        return acc;
      }, {});
      if (Object.keys(counts).length === 0) return;

      this.charts.guards = new ApexCharts(el, {
        series: Object.values(counts),
        chart: { type: 'donut', height: 140 },
        labels: Object.keys(counts),
        colors: ['#6366f1', '#10b981', '#f59e0b', '#ef4444'],
        legend: { show: false },
        plotOptions: { pie: { donut: { size: '70%' } } },
        dataLabels: { enabled: false },
        tooltip: { theme: document.documentElement.getAttribute('data-bs-theme') === 'dark' ? 'dark' : 'light' },
      });
      this.charts.guards.render();
    },
  }));

  Alpine.data('accessForm', () => ({
    type: 'roles',
    editingId: null,
    saving: false,
    permissionsLoading: false,
    permissionsError: '',
    permissionSearch: '',
    permissions: [],
    form: {
      name: '',
      guard_name: 'web',
      permissions: [],
      roles: [],
    },
    rolesList: [],

    get title() {
      if (this.editingId) return this.type === 'roles' ? 'Edit Role' : 'Edit Permission';
      return this.type === 'roles' ? 'Add Role' : 'Add Permission';
    },

    get groupedPermissions() {
      const query = this.permissionSearch.trim().toLowerCase();
      if (!query) return groupPermissions(this.permissions);

      return groupPermissions(this.permissions.filter(permission => {
        const name = String(permission.name ?? '').toLowerCase();
        const label = String(permission.actionLabel ?? '').toLowerCase();
        const group = permissionGroupFor(permission.name).label.toLowerCase();
        return name.includes(query) || label.includes(query) || group.includes(query);
      }));
    },

    get totalPermissionsCount() {
      return this.permissions.length;
    },

    get selectedGroups() {
      return groupPermissions(this.permissions.filter(permission => this.isPermissionSelected(permission.name)));
    },

    async init() {
      await Promise.all([this.loadPermissions(), this.loadRoles()]);
      document.getElementById('accessModal')?.addEventListener('hidden.bs.modal', () => this.resetForm(this.type));
    },

    async loadPermissions() {
      this.permissionsLoading = true;
      this.permissionsError = '';
      try {
        const data = await apiFetch(`/api/permissions/options?_t=${Date.now()}`);
        this.permissions = (data.data ?? data).map(permission => ({
          ...permission,
          actionLabel: permissionActionLabel(permission.name),
        }));
      } catch (err) {
        try {
          const data = await apiFetch('/api/permissions?per_page=500&deleted=without&sort_by=name&sort_dir=asc');
          this.permissions = (data.data ?? data).map(permission => ({
            ...permission,
            actionLabel: permissionActionLabel(permission.name),
          }));
        } catch (fallbackErr) {
          this.permissions = [];
          this.permissionsError = fallbackErr.message || err.message;
        }
      } finally {
        this.permissionsLoading = false;
      }
    },

    async loadRoles() {
      try {
        const data = await apiFetch(`/api/roles/options?_t=${Date.now()}`);
        this.rolesList = (data.data ?? data).map(role => role.name);
      } catch (err) {
        try {
          const data = await apiFetch('/api/roles?per_page=500&deleted=without&sort_by=name&sort_dir=asc');
          this.rolesList = (data.data ?? data).map(role => role.name);
        } catch (fallbackErr) {
          this.rolesList = [];
        }
      }
    },

    resetForm(type = 'roles') {
      this.type = type;
      this.editingId = null;
      this.saving = false;
      this.form = {
        name: '',
        guard_name: 'web',
        permissions: [],
        roles: [],
      };
      this.permissionSearch = '';
      if (type === 'roles') this.loadPermissions();
    },

    editItem(type, item) {
      this.resetForm(type);
      this.editingId = item.id;
      this.form.name = item.name;
      this.form.guard_name = item.guard_name || 'web';
      this.form.permissions = type === 'roles' ? (item.permissions ?? []).map(permission => permission.name) : [];
      this.form.roles = type === 'permissions' ? (item.roles ?? []).map(r => r.name) : [];
    },

    isPermissionSelected(permissionName) {
      return this.form.permissions.includes(permissionName);
    },

    isPermissionGroupSelected(group) {
      return group.items.length > 0 && group.items.every(permission => this.isPermissionSelected(permission.name));
    },

    selectedPermissionCount(group) {
      return group.items.filter(permission => this.isPermissionSelected(permission.name)).length;
    },

    togglePermissionGroup(group) {
      const groupNames = group.items.map(permission => permission.name);
      if (this.isPermissionGroupSelected(group)) {
        this.form.permissions = this.form.permissions.filter(permission => !groupNames.includes(permission));
        return;
      }

      this.form.permissions = [...new Set([...this.form.permissions, ...groupNames])];
    },

    selectAllPermissions() {
      this.form.permissions = this.permissions.map(permission => permission.name);
    },

    clearPermissions() {
      this.form.permissions = [];
    },

    async saveItem() {
      if (!this.form.name) {
        showToast('Name is required.', 'warning');
        return;
      }

      this.saving = true;
      try {
        const payload = {
          name: this.form.name,
          guard_name: this.form.guard_name || 'web',
        };
        if (this.type === 'roles') payload.permissions = this.form.permissions;
        if (this.type === 'permissions') payload.roles = this.form.roles;

        const url = this.editingId ? `${endpointFor(this.type)}/${this.editingId}` : endpointFor(this.type);
        const method = this.editingId ? 'PUT' : 'POST';
        const res = await apiFetch(url, { method, body: JSON.stringify(payload) });
        showToast(res.message || 'Saved successfully.');
        getModal('#accessModal')?.hide();
        const table = Alpine.$data(document.querySelector('[x-data="rolesPermissionsTable"]'));
        if (table) {
          await Promise.all([table.loadRoles(), table.loadPermissions()]);
          table.$nextTick(() => {
            table.clearExistingCharts();
            table.initCharts();
          });
        }
        await this.loadPermissions();
      } catch (err) {
        showToast(`Save failed: ${err.message}`, 'danger');
      } finally {
        this.saving = false;
      }
    },
  }));

  Alpine.data('accessProfile', () => ({
    type: 'roles',
    item: null,
    loading: false,

    get relatedItems() {
      if (!this.item) return [];
      return this.type === 'roles' ? (this.item.permissions ?? []) : (this.item.roles ?? []);
    },

    get groupedRelatedItems() {
      if (!this.item || this.type !== 'roles') return [];
      return groupPermissions(this.item.permissions ?? []);
    },

    editFromProfile() {
      if (!this.item) return;
      getModal('#accessViewModal')?.hide();
      this.$nextTick(() => {
        const table = Alpine.$data(document.querySelector('[x-data="rolesPermissionsTable"]'));
        if (table) {
          table.activeTab = this.type;
          table.editItem(this.item);
        }
      });
    },
  }));

  Alpine.data('accessImportForm', () => ({
    file: null,
    importing: false,
    result: null,

    handleFile(event) {
      this.file = event.target.files?.[0] ?? null;
      this.result = null;
    },

    async importItems() {
      if (!this.file) {
        showToast('Please select a CSV file.', 'warning');
        return;
      }

      this.importing = true;
      this.result = null;
      const text = await this.file.text();
      const lines = text.trim().split('\n').filter(line => line.trim());
      let created = 0;
      const errors = [];

      for (let i = 1; i < lines.length; i++) {
        const [typeRaw, name, guardName, permissionsRaw] = parseCsvLine(lines[i]);
        const type = String(typeRaw ?? '').toLowerCase() === 'permission' ? 'permissions' : 'roles';
        if (!name) {
          errors.push(`Row ${i + 1}: missing name`);
          continue;
        }

        const payload = {
          name,
          guard_name: guardName || 'web',
        };
        if (type === 'roles') {
          payload.permissions = String(permissionsRaw ?? '').split('|').map(value => value.trim()).filter(Boolean);
        }

        try {
          await apiFetch(endpointFor(type), { method: 'POST', body: JSON.stringify(payload) });
          created++;
        } catch (err) {
          errors.push(`Row ${i + 1} (${name}): ${err.message}`);
        }
      }

      this.importing = false;
      this.result = { created, errors };
      if (created > 0) {
        showToast(`Imported ${created} record(s) successfully.`);
        const table = Alpine.$data(document.querySelector('[x-data="rolesPermissionsTable"]'));
        if (table) await Promise.all([table.loadRoles(), table.loadPermissions()]);
      }
    },
  }));
});

import Alpine from 'alpinejs';
import { Modal } from 'bootstrap';
import Swal from 'sweetalert2';
import ApexCharts from 'apexcharts';

function showToast(message, type = 'success') {
    const container = document.getElementById('toast-container');
    if (!container) return;

    const id = 'toast-' + Date.now();
    const iconMap = {
        success: 'bi-check-circle-fill',
        danger:  'bi-x-circle-fill',
        warning: 'bi-exclamation-triangle-fill',
        info:    'bi-info-circle-fill',
        error:   'bi-x-circle-fill',
    };

    const el = document.createElement('div');
    el.id = id;
    el.className = `toast align-items-center text-bg-${type === 'error' ? 'danger' : type} border-0 show mb-2`;
    el.setAttribute('role', 'alert');
    el.innerHTML = `
        <div class="d-flex">
            <div class="toast-body">
                <i class="bi ${iconMap[type] ?? 'bi-info-circle-fill'} me-2"></i><span></span>
            </div>
            <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast"></button>
        </div>`;
    el.querySelector('.toast-body span').textContent = message;

    container.appendChild(el);
    setTimeout(() => el.remove(), 4000);
}

async function confirmDelete({ title, text, confirmButtonText = 'Yes, delete it' }) {
    const result = await Swal.fire({
        title,
        text,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonText,
        cancelButtonText: 'Cancel',
        confirmButtonColor: '#dc3545',
        reverseButtons: true,
        focusCancel: true,
    });

    return result.isConfirmed;
}

export default () => {
    const instance = {
        items: [],
        paginator: {
            current_page: 1,
            last_page: 1,
            total: 0,
            from: 0,
            to: 0,
            per_page: 10
        },
        stats: { total: 0, active: 0, inactive: 0 },

        charts: {},
        chartsInitialized: false,
        statusStats: [],

        searchQuery: '',
        statusFilter: '',
        sortField: 'id',
        sortDirection: 'desc',
        currentPage: 1,
        itemsPerPage: 10,
        selectedItems: [],

        isLoading: false,
        saving: false,
        isEditing: false,

        apiBase: '/api/shipping/services',
        modalInstance: null,
        providerUsers: [],

        form: {
            id: null,
            code: '',
            name: '',
            description: '',
            is_active: true,
            provider_user_ids: []
        },

        bulkAssignForm: {
            provider_ids: []
        },
        bulkAssignModalInstance: null,
        providerSearch: '',

        get filteredProviderUsers() {
            if (!this.providerSearch) return this.providerUsers;
            const term = this.providerSearch.toLowerCase();
            return this.providerUsers.filter(u => 
                (u.name || '').toLowerCase().includes(term) ||
                (u.email || '').toLowerCase().includes(term) ||
                (u.department || '').toLowerCase().includes(term) ||
                (u.phone || '').toLowerCase().includes(term)
            );
        },

        init() {
            this.loadData();
            this.loadProviderUsers();

            const modalEl = document.getElementById('servicesModal');
            if (modalEl) {
                this.modalInstance = Modal.getOrCreateInstance(modalEl);
                modalEl.addEventListener('hidden.bs.modal', () => {
                    this.resetForm();
                });
            }

            const bulkModalEl = document.getElementById('bulkAssignModal');
            if (bulkModalEl) {
                this.bulkAssignModalInstance = Modal.getOrCreateInstance(bulkModalEl);
                bulkModalEl.addEventListener('hidden.bs.modal', () => {
                    this.bulkAssignForm.provider_ids = [];
                });
            }

            setTimeout(() => {
                this.initCharts();
            }, 300);
        },

        initCharts() {
            if (this.chartsInitialized) {
                this.updateCharts();
                return;
            }
            this.renderTrendChart();
            this.renderStatusChart();
            this.chartsInitialized = true;
        },

        renderTrendChart() {
            const chartElement = document.getElementById('serviceTrendsChart');
            if (!chartElement) return;

            // Mock activity data
            const trendsData = {
                series: [{
                    name: 'Activity',
                    data: [5, 8, 12, 10, 15, 7, this.stats.total]
                }],
                chart: {
                    type: 'area',
                    height: 300,
                    toolbar: { show: false },
                    fontFamily: 'inherit'
                },
                colors: ['#8b5cf6'],
                fill: {
                    type: 'gradient',
                    gradient: { shadeIntensity: 1, opacityFrom: 0.7, opacityTo: 0.3 }
                },
                stroke: { curve: 'smooth', width: 2 },
                xaxis: {
                    categories: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
                }
            };

            this.charts.trends = new ApexCharts(chartElement, trendsData);
            this.charts.trends.render();
        },

        renderStatusChart() {
            const chartElement = document.getElementById('statusChart');
            if (!chartElement) return;

            const chartData = {
                series: this.statusStats.map(stat => stat.count),
                chart: { type: 'donut', height: 200 },
                labels: this.statusStats.map(stat => stat.name),
                colors: this.statusStats.map(stat => stat.color),
                plotOptions: { pie: { donut: { size: '70%' } } },
                legend: { show: false }
            };

            this.charts.status = new ApexCharts(chartElement, chartData);
            this.charts.status.render();
        },

        updateCharts() {
            if (this.charts.status) {
                this.charts.status.updateSeries(this.statusStats.map(stat => stat.count));
            }
        },

        async apiRequest(url, options = {}) {
            const { headers, ...otherOptions } = options;
            const response = await fetch(url, {
                headers: {
                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content,
                    'X-Requested-With': 'XMLHttpRequest',
                    'Accept': 'application/json',
                    'Content-Type': 'application/json',
                    ...(headers || {})
                },
                ...otherOptions,
            });

            const text = await response.text();
            const payload = text ? JSON.parse(text) : {};

            if (!response.ok) {
                const validation = payload?.errors ? Object.values(payload.errors).flat().join(' ') : '';
                const message = validation || payload?.message || payload?.error || 'Request failed.';
                throw new Error(message);
            }
            return payload;
        },

        async loadData() {
            this.isLoading = true;
            try {
                // Fetch stats from all items
                const allPayload = await this.apiRequest(`${this.apiBase}?per_page=100`);
                const allItems = allPayload.data || [];
                this.stats.total = allItems.length;
                this.stats.active = allItems.filter(i => i.is_active).length;
                this.stats.inactive = allItems.filter(i => !i.is_active).length;

                this.statusStats = [
                    { name: 'Active', count: this.stats.active, percentage: this.stats.total ? Math.round((this.stats.active / this.stats.total) * 100) : 0, color: '#10b981' },
                    { name: 'Inactive', count: this.stats.inactive, percentage: this.stats.total ? Math.round((this.stats.inactive / this.stats.total) * 100) : 0, color: '#64748b' }
                ].filter(stat => stat.count > 0);

                if (this.chartsInitialized) {
                    this.updateCharts();
                }

                // Fetch paginated active list
                let query = `page=${this.currentPage}&per_page=${this.itemsPerPage}&search=${encodeURIComponent(this.searchQuery)}&sort_by=${this.sortField}&sort_dir=${this.sortDirection}`;
                if (this.statusFilter !== '') query += `&is_active=${this.statusFilter}`;

                const payload = await this.apiRequest(`${this.apiBase}?${query}`);
                this.items = payload.data || [];
                this.paginator = {
                    current_page: payload.current_page,
                    last_page: payload.last_page,
                    total: payload.total,
                    from: payload.from || 0,
                    to: payload.to || 0,
                    per_page: payload.per_page
                };
            } catch (error) {
                console.error('Failed to load services:', error);
                showToast(error.message, 'error');
            } finally {
                this.isLoading = false;
            }
        },

        async loadProviderUsers() {
            try {
                this.providerUsers = await this.apiRequest(`${this.apiBase}/provider-options`);
            } catch (error) {
                console.error('Failed to load service providers:', error);
                showToast(error.message, 'error');
            }
        },

        filterData() {
            this.currentPage = 1;
                        this.loadData();
        },

        clearFilters() {
            this.searchQuery = '';
            this.statusFilter = '';
            this.currentPage = 1;
            this.loadData();
        },

        hasActiveAdvancedFilters() {
            return Boolean(this.statusFilter !== '');
        },

        toggleAll(checked) {
            if (checked) {
                this.selectedItems = this.items.map(i => String(i.id));
            } else {
                this.selectedItems = [];
            }
        },

        openBulkAssignModal() {
            if (this.selectedItems.length === 0) return;
            this.bulkAssignForm.provider_ids = [];
            this.bulkAssignModalInstance?.show();
        },

        async bulkAssignProvider() {
            if (this.bulkAssignForm.provider_ids.length === 0 || this.selectedItems.length === 0) return;

            this.saving = true;
            try {
                await this.apiRequest(`${this.apiBase}/bulk-action`, {
                    method: 'POST',
                    body: JSON.stringify({
                        action: 'assign_provider',
                        ids: this.selectedItems,
                        provider_ids: this.bulkAssignForm.provider_ids
                    })
                });

                showToast(`Providers assigned successfully to ${this.selectedItems.length} service(s).`, 'success');
                this.selectedItems = [];
                this.bulkAssignModalInstance?.hide();
                await this.loadData();
            } catch (error) {
                showToast(error.message || 'Failed to assign provider.', 'error');
            } finally {
                this.saving = false;
            }
        },

        async bulkAction(action) {
            if (this.selectedItems.length === 0) return;

            const actionLabels = {
                activate: 'activate',
                deactivate: 'deactivate',
                delete: 'delete'
            };

            const result = await Swal.fire({
                title: 'Confirm Bulk Action',
                text: `Are you sure you want to ${actionLabels[action]} ${this.selectedItems.length} service(s)?`,
                icon: action === 'delete' ? 'warning' : 'question',
                showCancelButton: true,
                confirmButtonColor: action === 'delete' ? '#dc3545' : '#3085d6',
                cancelButtonColor: '#6c757d',
                confirmButtonText: 'Yes, proceed'
            });

            if (!result.isConfirmed) return;

            this.isLoading = true;
            try {
                await this.apiRequest(`${this.apiBase}/bulk-action`, {
                    method: 'POST',
                    body: JSON.stringify({
                        action: action,
                        ids: this.selectedItems
                    })
                });

                showToast(`Bulk action completed successfully.`, 'success');
                this.selectedItems = [];
                this.loadData();
            } catch (error) {
                showToast(error.message || 'Bulk action failed.', 'error');
                this.isLoading = false;
            }
        },

        sortBy(field) {
            if (this.sortField === field) {
                this.sortDirection = this.sortDirection === 'asc' ? 'desc' : 'asc';
            } else {
                this.sortField = field;
                this.sortDirection = 'asc';
            }
            this.loadData();
        },

        goToPage(page) {
            if (page >= 1 && page <= this.paginator.last_page) {
                this.currentPage = page;
                this.loadData();
            }
        },

        get visiblePages() {
            const total = this.paginator.last_page;
            if (total <= 1) return [1];
            const pages = [];
            pages.push(1);

            if (total <= 7) {
                for (let i = 2; i <= total; i++) pages.push(i);
            } else {
                if (this.currentPage <= 4) {
                    for (let i = 2; i <= 5; i++) pages.push(i);
                    pages.push('...');
                    pages.push(total);
                } else if (this.currentPage >= total - 3) {
                    pages.push('...');
                    for (let i = total - 4; i <= total; i++) pages.push(i);
                } else {
                    pages.push('...');
                    for (let i = this.currentPage - 1; i <= this.currentPage + 1; i++) pages.push(i);
                    pages.push('...');
                    pages.push(total);
                }
            }
            return pages;
        },

        resetForm() {
            this.isEditing = false;
            this.form = {
                id: null,
                code: '',
                name: '',
                description: '',
                is_active: true,
                provider_user_ids: []
            };
        },

        openCreateModal() {
            this.resetForm();
            this.modalInstance?.show();
        },

        editItem(item) {
            this.isEditing = true;
            this.form = {
                id: item.id,
                code: item.code,
                name: item.name,
                description: item.description || '',
                is_active: !!item.is_active,
                provider_user_ids: (item.providers || []).map(provider => String(provider.id))
            };
            this.modalInstance?.show();
        },

        async saveItem() {
            this.saving = true;
            try {
                const url = this.isEditing ? `${this.apiBase}/${this.form.id}` : this.apiBase;
                const method = this.isEditing ? 'PATCH' : 'POST';

                await this.apiRequest(url, {
                    method,
                    body: JSON.stringify(this.form)
                });

                showToast(`Successfully ${this.isEditing ? 'updated' : 'created'} shipping service.`, 'success');
                this.modalInstance?.hide();
                await this.loadData();
            } catch (error) {
                showToast(error.message, 'error');
            } finally {
                this.saving = false;
            }
        },

        async toggleActive(item) {
            try {
                await this.apiRequest(`${this.apiBase}/${item.id}/toggle`, { method: 'POST' });
                showToast(`Status updated for "${item.name}".`, 'success');
                await this.loadData();
            } catch (error) {
                showToast(error.message, 'error');
            }
        },

        async deleteItem(item) {
            const confirmed = await confirmDelete({
                title: 'Delete Shipping Service?',
                text: `Are you sure you want to delete "${item.name}"? This action cannot be undone.`
            });
            if (!confirmed) return;

            try {
                await this.apiRequest(`${this.apiBase}/${item.id}`, { method: 'DELETE' });
                showToast('Shipping service deleted successfully.', 'success');
                await this.loadData();
            } catch (error) {
                showToast(error.message, 'error');
            }
        }
    };

    window.Alpine.store('shippingServices', instance);
    return instance;
};

